from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.close_prices = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket = None
        self.minute_bars = {}

        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        now = self.Time
        current_date = now.date()

        # Immediately remove unexpected SPY equity created by exercise/assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.no_entry_date = current_date

            if (
                self.equity_liquidation_ticket is None
                or not self._ticket_is_open(self.equity_liquidation_ticket)
            ):
                self.Debug(
                    f"{now}: Unexpected SPY equity position detected; "
                    f"liquidating {spy_quantity} shares."
                )
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )

        # Process the current SPY minute bar for five-minute aggregation.
        if self.spy in data.Bars:
            minute_bar = data.Bars[self.spy]
            self._process_minute_bar(minute_bar, data)

        # Manage an existing option position on every minute Slice.
        self._process_option_exit(data)

    def _process_minute_bar(self, minute_bar: TradeBar, data: Slice):
        local_time = self.Time
        minute = local_time.hour * 60 + local_time.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute < session_start or minute >= session_end:
            return

        bucket_index = (minute - session_start) // 5
        bucket = (local_time.date(), bucket_index)

        if self.minute_bucket is not None and bucket != self.minute_bucket:
            self._discard_incomplete_bucket()

        if self.minute_bucket != bucket:
            self.minute_bucket = bucket
            self.minute_bars = {}

        # Use the minute's session-clock position as its identity.
        self.minute_bars[minute] = minute_bar

        # A five-minute bar ending at 09:35 contains 09:30 through 09:34.
        if minute % 5 != 4:
            return

        expected_minutes = list(range(minute - 4, minute + 1))
        if any(m not in self.minute_bars for m in expected_minutes):
            self._discard_incomplete_bucket()
            return

        bars = [self.minute_bars[m] for m in expected_minutes]
        consolidated_close = bars[-1].Close
        bar_end = local_time + timedelta(minutes=1)

        self.close_prices.append(float(consolidated_close))

        if len(self.close_prices) < 20:
            self.minute_bucket = None
            self.minute_bars = {}
            return

        current_fast = sum(list(self.close_prices)[-5:]) / 5.0
        current_slow = sum(self.close_prices) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        self.minute_bucket = None
        self.minute_bars = {}

        if bullish_cross:
            eligible = (
                bar_end.hour > 9
                or (bar_end.hour == 9 and bar_end.minute >= 45)
            ) and (
                bar_end.hour < 14
                or (bar_end.hour == 14 and bar_end.minute <= 30)
            )

            if eligible:
                self._try_enter(data, float(consolidated_close), bar_end)

    def _discard_incomplete_bucket(self):
        self.minute_bucket = None
        self.minute_bars = {}

    def _try_enter(self, data: Slice, spy_price: float, signal_time):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.entry_order_id is not None:
            return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested or holding.Quantity != 0:
                return

        chain = None
        try:
            chain = data.OptionChains.get(self.option)
        except Exception:
            chain = None

        if not chain:
            self.Debug(f"{signal_time}: Skipped entry; no option chain.")
            return

        contracts = []
        for contract in chain:
            try:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= current_date + timedelta(days=7)
                ):
                    contracts.append(contract)
            except Exception:
                continue

        if not contracts:
            self.Debug(
                f"{signal_time}: Skipped entry; no qualifying expiration."
            )
            return

        expiration_date = min(c.Expiry.date() for c in contracts)
        expiration_contracts = [
            c for c in contracts if c.Expiry.date() == expiration_date
        ]

        minimum_strike = 1.01 * spy_price
        eligible = [
            c for c in expiration_contracts
            if c.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug(
                f"{signal_time}: Skipped entry; no qualifying strike."
            )
            return

        selected = sorted(
            eligible,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )[0]

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{signal_time}: Submitted entry for {selected.Symbol} "
            f"at expiration {expiration_date}."
        )

    def _process_option_exit(self, data: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiration_date = self.entry_symbol.ID.Date.date()
        current_date = self.Time.date()

        # Do not intentionally hold through expiration.
        if current_date >= expiration_date:
            self.no_entry_date = current_date
            self._submit_exit("Expiration liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)

        # Time stop at 15:45 on the trading day before expiration.
        if (
            current_date == previous_trading_day
            and (
                self.Time.hour > 15
                or (self.Time.hour == 15 and self.Time.minute >= 45)
            )
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        # Profit target requires a strictly positive current bid and ask.
        contract = None
        try:
            chain = data.OptionChains.get(self.option)
            if chain:
                for candidate in chain:
                    if candidate.Symbol == self.entry_symbol:
                        contract = candidate
                        break
        except Exception:
            contract = None

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(
            self.exit_ticket
        ):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            f"{self.Time}: Submitted option liquidation for "
            f"{self.entry_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled for {self.entry_symbol} "
                    f"at {self.entry_price}."
                )
                self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.Debug(
                        f"{self.Time}: Entry order ended with status "
                        f"{order_event.Status}."
                    )
                    self.entry_order_id = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: Option exit filled for "
                f"{order_event.Symbol} at {order_event.FillPrice}."
            )
            self.exit_ticket = None
            self.entry_symbol = None
            self.entry_price = None

        if (
            self.equity_liquidation_ticket is not None
            and order_event.OrderId == self.equity_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: SPY equity liquidation filled after "
                f"exercise/assignment."
            )
            self.equity_liquidation_ticket = None

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        return exchange_hours.GetPreviousTradingDay(date_value).date()

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
