from AlgorithmImports import *
from datetime import timedelta


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetDataNormalizationMode(DataNormalizationMode.Raw)
        option.SetFilter(
            lambda universe: universe
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.previous_averages_ready = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.pending_signal = False
        self.expiration_block_date = None
        self.last_trading_date = None
        self.underlying_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        current_time = bar.EndTime.time()

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None
        self.previous_averages_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if current_time < time(9, 45) or current_time > time(14, 30):
            return

        if not self.previous_averages_ready:
            return

        if (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.last_trading_date != current_date:
            self.last_trading_date = current_date
            self.underlying_liquidation_ticket = None

        # Immediately liquidate any SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0 and self.underlying_liquidation_ticket is None:
            self.Debug(
                f"Unexpected exercise/assignment: liquidating {spy_quantity} SPY"
            )
            self.underlying_liquidation_ticket = self.MarketOrder(
                self.spy, -spy_quantity
            )

        # Expiration processing and time-stop handling.
        if self.held_option is not None:
            expiration = self.held_option.ID.Date.date()

            if current_date >= expiration:
                self.expiration_block_date = current_date
                self.SubmitExit("expiration")
            else:
                previous_trading_day = self.GetPreviousTradingDay(expiration)

                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self.SubmitExit("pre-expiration time stop")

                self.CheckProfitTarget(slice)

        # Evaluate the signal exactly once after the completed bar.
        if not self.pending_signal:
            return

        self.pending_signal = False

        if current_date == self.expiration_block_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable")
            return

        current_spy_price = slice.Bars[self.spy].Close
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        minimum_expiration = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away")
            return

        selected_expiration = expirations[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract for contract in chain
            if (
                contract.Expiry.date() == selected_expiration
