        )

        if self.bucket_start is None:
            self._start_bucket(current_bucket, bar)
            return

        if current_bucket != self.bucket_start:
            self._complete_bucket(slice)
            self._start_bucket(current_bucket, bar)
            return

        self.bucket_high = max(self.bucket_high, bar.High)
        self.bucket_low = min(self.bucket_low, bar.Low)
        self.bucket_close = bar.Close
        self.bucket_volume += bar.Volume

    def _start_bucket(self, bucket_start, bar):
        self.bucket_start = bucket_start
        self.bucket_open = bar.Open
        self.bucket_high = bar.High
        self.bucket_low = bar.Low
        self.bucket_close = bar.Close
        self.bucket_volume = bar.Volume

    def _complete_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        bar_end = self.bucket_start + timedelta(minutes=5)
        close = self.bucket_close

        self.closes.append(close)

        if len(self.closes) >= 20:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

            bullish_cross = (
                self.previous_fast is not None and
                self.previous_slow is not None and
                self.previous_fast <= self.previous_slow and
                current_fast > current_slow
            )

            if (
                bullish_cross and
                time(9, 45) <= bar_end.time() <= time(14, 30)
            ):
                self._try_enter(slice, bar_end)

            self.previous_fast = current_fast
            self.previous_slow = current_slow

