            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no call contracts in current chain.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        valid_expirations = sorted({
            contract.Expiration.date()
            for contract in contracts
            if contract.Expiration.date() >= minimum_expiration
        })

