            return

        selected_expiration = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        eligible = [
            contract for contract in contracts
            if contract.Expiration.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug("Skipped entry: no qualifying strike at selected expiration.")
            return

        selected = sorted(
            eligible,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiration,
                selected.Strike
            )
        )

    def _process_position_exits(self, slice: Slice):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()
        today = self.Time.date()

        # Expiration processing begins at the start of expiration day.
        if today >= expiration_date:
            self.expiration_blocked_date = today
            self._submit_option_exit("Expiration-day protection")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)

        if (
            today == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("Expiration-eve time stop")
            return

        if self.exit_ticket is not None or self.entry_price is None:
            return

        quote = self._find_held_contract(slice)
        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50 percent profit target")

    def _submit_option_exit(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_option.Symbol,
                reason
            )
        )

    def _find_held_contract(self, slice: Slice):
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_option.Symbol:
                    return contract
        return None

    def _has_option_position(self):
        if self.held_option is not None:
            return self.Portfolio[self.held_option.Symbol].Quantity != 0

        for security in self.Portfolio.Values:
            if (
                security.Type == SecurityType.Option and
                security.Quantity != 0
            ):
                return True

        return False

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.expiration_blocked_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment detected: {}".format(
                    order_event.Symbol
                )
            )

            equity_quantity = self.Portfolio[self.spy].Quantity
            if equity_quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -equity_quantity,
                    tag="Liquidate unexpected assignment equity"
                )
                self.Debug("Liquidated SPY equity created by assignment.")

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
