        if minute_of_day < 571 or minute_of_day > 960:
            return None

        bucket_end_minute = 575 + ((minute_of_day - 571) // 5) * 5
        bucket_key = (bar_date, bucket_end_minute)

        if self.minute_bucket_key != bucket_key:
            completed = self._finish_minute_bucket()

            self.minute_bucket_key = bucket_key
            self.minute_bucket = {
