                    and self.Portfolio[self.held_symbol].Quantity == 0
                ):
                    self.held_symbol = None
                    self.held_expiration = None
                    self.entry_price = None
                    self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        is_special_processing = (
            bool(getattr(order_event, "IsAssignment", False))
            or bool(getattr(order_event, "IsExercise", False))
            or "assignment" in message
            or "exercise" in message
        )

        if is_special_processing:
            self.Debug("Unexpected option exercise or assignment processed.")
            self._liquidate_unexpected_spy_equity()
