                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_bucket_start = None
        self.pending_minutes = {}

        self.entry_ticket = None
        self.entry_open = False
        self.held_symbol = None
        self.entry_price = None
        self.held_expiration = None
        self.time_stop_date = None

        self.exit_ticket = None
        self.exit_submitted = False
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Prevent replacement entries on the expiration date.
        if self.held_expiration is not None and today >= self.held_expiration:
            self.expiration_block_date = today

            if self.entry_open and self.entry_ticket is not None:
                self.entry_ticket.Cancel("Expiration processing began")
                self.entry_open = False

            if self.held_symbol is not None:
                self._submit_exit("Expiration liquidation")

        # Immediately liquidate unexpected SPY equity positions.
        if self.Portfolio[self.spy].Quantity != 0:
            quantity = self.Portfolio[self.spy].Quantity
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; "
                f"liquidating {quantity} shares."
            )
            self.MarketOrder(self.spy, -quantity, "Unexpected exercise/assignment")

        # Evaluate exits on every minute Slice.
        if self.held_symbol is not None and not self.exit_submitted:
            self._evaluate_exits(slice)

        # Do not consolidate absent minute bars or process entries while occupied.
        if self.spy not in slice.Bars:
            return

        if self.held_symbol is not None or self.entry_open:
            return

        minute_bar = slice.Bars[self.spy]
        bar_time = minute_bar.Time

        if not self._is_regular_session_minute(bar_time):
            return

        bucket_start = self._bucket_start(bar_time)

        if (
            self.pending_bucket_start is not None
            and bucket_start != self.pending_bucket_start
        ):
            self._finish_pending_bucket()

        if self.pending_bucket_start != bucket_start:
            self.pending_bucket_start = bucket_start
            self.pending_minutes = {}

