        if len(self.pending_minutes) == 5:
            expected = {
                bucket_start + timedelta(minutes=i)
                for i in range(5)
            }

            if set(self.pending_minutes.keys()) == expected:
                close = self.pending_minutes[
                    bucket_start + timedelta(minutes=4)
                ].Close
                bar_end = bucket_start + timedelta(minutes=5)
                self._process_five_minute_close(
