        t = time_value.time()
        return (
            t >= datetime.strptime("09:30", "%H:%M").time()
            and t < datetime.strptime("16:00", "%H:%M").time()
        )

    def _bucket_start(self, time_value):
        session_start = time_value.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        elapsed_minutes = int((time_value - session_start).total_seconds() // 60)
        return session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

