        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        end_time = bar_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not (eligible_start <= end_time <= eligible_end):
            return

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self._attempt_entry(slice, current_spy_price)

    def _attempt_entry(self, slice, spy_price):
        if self.expiration_block_date == self.Time.date():
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        if spy_price is None or spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped; invalid SPY price.")
            return

        chain = slice.OptionChains[self.option_symbol]
        contracts = list(chain)

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expirations:
            self.Debug(f"{self.Time}: Entry skipped; no eligible expiration.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying call at "
                f"{selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute SMA crossover"
        )
        self.entry_open = True

    def _evaluate_exits(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        # The scheduled time stop applies independently of option quotes.
        if (
            self.held_expiration is not None
            and self.time_stop_date == self.Time.date()
            and self.Time.time() >= datetime.strptime(
                "15:45", "%H:%M"
            ).time()
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        if self.held_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.held_symbol]
        bid = getattr(bar, "Bid", None)
        ask = getattr(bar, "Ask", None)

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

