                .Expiration(0, 365)
        )
        self.spy_option = option

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # TradeBarConsolidator emits only bars containing actual minute data.
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            end_time = bar.EndTime
            if 9 <= end_time.hour <= 14:
                eligible = (
                    (end_time.hour == 9 and end_time.minute >= 45)
                    or (10 <= end_time.hour <= 13)
                    or (end_time.hour == 14 and end_time.minute <= 30)
                )
                if eligible:
                    self.pending_signal_end = end_time

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice):
        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            self._evaluate_held_position(slice)
            return

        if self.entry_ticket is not None and not self._ticket_is_closed(self.entry_ticket):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.pending_signal_end is None:
            return

        signal_end = self.pending_signal_end
        self.pending_signal_end = None

        # Process the signal once, using the Slice at the completed bar.
        if signal_end.date() != self.Time.date():
            return

        self._try_enter(slice)

    def _try_enter(self, slice):
        if self.held_symbol is not None:
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        current_price = float(slice.Bars[self.spy].Close)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = 1.01 * current_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol, selected_expiration, selected.Strike
            )
        )

    def _evaluate_held_position(self, slice):
        if self.held_symbol is None:
            return

        current_date = self.Time.date()

        # Expiration-day safeguard.
        if self.expiration is not None and current_date >= self.expiration.date():
            self.no_entry_date = current_date
            self._cancel_entry_order()
            self._submit_exit("expiration safeguard")
            return

        # Time stop on the trading day immediately preceding expiration.
        if self.expiration is not None:
            previous_trading_day = self._previous_trading_day(
                self.expiration.date()
            )
            if (
                current_date == previous_trading_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("time stop")
                return

        # Profit target requires a strictly positive current bid and ask.
        contract = None
        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is not None:
