            self.Liquidate(self.spy, "unexpected exercise or assignment")
            self.expiration_block_date = today

        self._process_expiration(today)

        if slice.Bars.ContainsKey(self.spy):
            self._update_five_minute_bar(slice.Bars[self.spy])

        if self.entry_signal_pending:
            self.entry_signal_pending = False
            self._try_enter(slice)

        self._evaluate_exit(slice, today)

    def _update_five_minute_bar(self, minute_bar):
        t = self.Time.replace(second=0, microsecond=0)

        if t.weekday() >= 5:
            return
        if t < t.replace(hour=9, minute=30):
            return
        if t > t.replace(hour=16, minute=0):
            return

        session_start = t.replace(hour=9, minute=30)
        elapsed_minutes = int((t - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self.five_bar is None or self.five_bar["start"] != bucket_start:
            # Require the first actual minute of every bucket.
            if t != bucket_start:
                self.five_bar = None
                return

            self.five_bar = {
                "start": bucket_start,
                "count": 1,
                "close": float(minute_bar.Close),
                "last_time": t
            }
            return

        expected = self.five_bar["last_time"] + timedelta(minutes=1)
        if t != expected:
            self.five_bar = None
            return

        self.five_bar["count"] += 1
        self.five_bar["close"] = float(minute_bar.Close)
        self.five_bar["last_time"] = t

        if self.five_bar["count"] != 5:
            return

        bar_end = self.five_bar["start"] + timedelta(minutes=5)
        close = self.five_bar["close"]
        self.five_bar = None
        self._on_completed_five_minute_bar(bar_end, close)

    def _on_completed_five_minute_bar(self, end_time, close):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(close)

        current_fast = None
        current_slow = None

        if len(self.closes) >= self.fast_period:
            current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period

        if len(self.closes) == self.slow_period:
            current_slow = sum(self.closes) / self.slow_period

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            prior_fast is None
            or prior_slow is None
            or current_fast is None
            or current_slow is None
        ):
            return

        bullish_cross = (
            prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        end_minutes = end_time.hour * 60 + end_time.minute
        if not 9 * 60 + 45 <= end_minutes <= 14 * 60 + 30:
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self._has_option_holding():
            return

        if self._entry_order_open():
            return

        self.entry_signal_pending = True

    def _try_enter(self, slice):
        if self._has_option_holding() or self._entry_order_open():
            return

        if self.expiration_block_date == self.Time.date():
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Entry skipped: no option chain")
            return

        chain = slice.OptionChains[self.option.Symbol]
        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiration.date()
            for contract in chain
            if contract.Expiration.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Entry skipped: no expiration at least 7 days out")
            return

        expiration = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiration.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call contract")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )

        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_exit(self, slice, today):
        if self.held_symbol is None or self.entry_price is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        expiration = self.held_symbol.ID.Date.date()

        if today >= expiration:
            self.expiration_block_date = today
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiration)

        if (
            today == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("expiration time stop")
            return

        quote = self._get_current_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_symbol, reason))

    def _get_current_quote(self, slice, symbol):
        if slice.QuoteBars.ContainsKey(symbol):
            quote_bar = slice.QuoteBars[symbol]
            bid = quote_bar.Bid.Close if quote_bar.Bid is not None else 0
            ask = quote_bar.Ask.Close if quote_bar.Ask is not None else 0
            return float(bid), float(ask)

        if slice.OptionChains.ContainsKey(self.option.Symbol):
            for contract in slice.OptionChains[self.option.Symbol]:
                if contract.Symbol == symbol:
                    return (
                        float(contract.BidPrice),
                        float(contract.AskPrice)
                    )

        return None

    def _process_expiration(self, today):
        if (
            self.held_symbol is not None
            and today >= self.held_symbol.ID.Date.date()
        ):
            self.expiration_block_date = today

    def _previous_trading_day(self, expiration):
        date = expiration - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(
            datetime.combine(date, datetime.min.time())
        ):
            date -= timedelta(days=1)

        return date

    def _has_option_holding(self):
        return any(
            security.Symbol.SecurityType == SecurityType.Option
            and security.Invested
            for security in self.Securities.Values
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order {}".format(order_event.Status))
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.exit_ticket.Tag))
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
