        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, reason={1}".format(
                self.held_option,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entry filled: {0}, fill price={1}".format(
                            self.held_option,
                            self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0}, fill price={1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if order_event.Symbol == self.spy:
            self.Debug(
                "Unexpected SPY equity order event: {0}, status={1}".format(
                    order_event.OrderId,
                    order_event.Status
                )
            )

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.blocked_entry_date = self.Time.date()
        self.Debug(
            "Unexpected option assignment/exercise: {0}".format(
                assignment_event.Symbol
            )
        )
        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and not self.equity_liquidation_submitted:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_submitted = True

        if quantity == 0:
            self.equity_liquidation_submitted = False

    def _has_expired_position(self):
        if self.held_option is None:
            return False

        expiration_date = self.held_option.ID.Date.date()

        if self.Time.date() >= expiration_date:
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("expiration processing")
            return True

        return False

    def _find_contract(self, slice, symbol):
        if self.option_symbol not in slice.OptionChains:
            return None

        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == symbol:
                return contract

        return None

    def _entry_order_is_open(self):
