            self.Debug("Unexpected SPY exercise/assignment; liquidating equity")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.blocked_date = self.Time.date()

        completed_bar = self._add_minute_bar(slice)

        if self.held_symbol is not None:
            self._process_held_option(slice)

        if completed_bar is not None:
            self._process_completed_bar(completed_bar, slice)

    def _add_minute_bar(self, slice):
        if self.spy not in slice.Bars:
            return None

        minute_bar = slice.Bars[self.spy]
        local_time = minute_bar.Time.replace(tzinfo=None)

        if local_time.date() != self.Time.date():
            return None

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return None

        elapsed = (
            local_time.hour * 60 + local_time.minute
            - (9 * 60 + 30)
        )
        bucket_end = local_time.replace(second=0, microsecond=0) + timedelta(
            minutes=5 - elapsed % 5
        )

        completed = None

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            completed = self._finish_bucket()
            self.bucket_bars = []

        self.bucket_end = bucket_end
        self.bucket_bars.append(minute_bar)

        return completed

    def _finish_bucket(self):
        bars = self.bucket_bars

        if len(bars) != 5:
            return None

        starts = [bar.Time.replace(tzinfo=None) for bar in bars]

        if any(
            starts[i] != starts[0] + timedelta(minutes=i)
            for i in range(5)
        ):
            return None

        return TradeBar(
            starts[0],
            self.spy,
            bars[0].Open,
