from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self.consolidator
        )

        self.closes = []
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.spy_exit_submitted = False

    def _on_five_minute_bar(self, sender, bar):
        end = bar.EndTime

        # Require regular-session bars aligned to New York five-minute boundaries.
        if end.time() < time(9, 35) or end.time() > time(16, 0):
            return
        if end.minute % 5 != 0:
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0

        self.closes.append(float(bar.Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        eligible_time = time(9, 45) <= end.time() <= time(14, 30)

        if (
            eligible_time
            and previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal = True

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately liquidate any unexpected SPY equity position.
        if self.Portfolio[self.spy].Invested:
            self.no_entry_date = today
            if not self.spy_exit_submitted:
                quantity = -self.Portfolio[self.spy].Quantity
                self.MarketOrder(self.spy, quantity)
                self.spy_exit_submitted = True
                self.Debug("Unexpected SPY exercise/assignment position liquidated.")
        else:
            self.spy_exit_submitted = False

        if self.held_symbol is not None:
            expiration = self.held_symbol.ID.Date.date()

            # Never intentionally hold through expiration.
            if today >= expiration:
                self.no_entry_date = today
                self._liquidate_option("expiration processing")
                return

            # Time stop on the trading day immediately preceding expiration.
            previous_trading_day = self._previous_trading_day(expiration)
            if (
                today == previous_trading_day
                and self.Time.time() >= time(15, 45)
            ):
                self._liquidate_option("expiration time stop")
                return

            self._check_profit_target(slice)

        # A signal is consumed once, even if its selection is skipped.
        if self.pending_signal:
            self.pending_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        current_price = float(slice.Bars[self.spy].Close)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiration = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiration {selected_expiration}, strike {selected.Strike}."
        )

    def _check_profit_target(self, slice: Slice):
        if self.entry_price is None or self._exit_order_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (contract for contract in chain
             if contract.Symbol == self.held_symbol),
            None
        )

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        self._cancel_open_exit()

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug(f"Exit submitted: {reason}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price {self.entry_price:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}.")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if (
            order_event.OrderType == OrderType.OptionExercise
            or "exercise" in message
            or "assignment" in message
            or "assigned" in message
        ):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise/assignment detected.")

            if self.Portfolio[self.spy].Invested:
                quantity = -self.Portfolio[self.spy].Quantity
                self.MarketOrder(self.spy, quantity)
                self.spy_exit_submitted = True
                self.Debug("Unexpected SPY position liquidated.")

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def _cancel_open_exit(self):
        if self._exit_order_open():
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Canceled before replacement market exit."
            )
        self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate
