        holding = self.Portfolio[self.held_option]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiration_date = self.Securities[
            self.held_option
        ].Symbol.ID.Date.date()

        if self.Time.date() >= expiration_date and self.Time.hour >= 9:
