        else:
            self.equity_liquidation_logged = False

    def IsExpirationEveTime(self):
        if self.held_option is None:
            return False

        expiration_date = self.Securities[
            self.held_option
        ].Symbol.ID.Date.date()

        previous_trading_day = self.GetPreviousTradingDay(expiration_date)
        return (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        )

    def GetPreviousTradingDay(self, expiration_date):
        start = datetime(
            expiration_date.year,
            expiration_date.month,
            expiration_date.day
        ) - timedelta(days=14)

        end = datetime(
            expiration_date.year,
            expiration_date.month,
            expiration_date.day
        )

        previous_day = None

        for trading_day in self.TradingCalendar.GetDays(start, end):
            day = trading_day.Date.date()
            if day < expiration_date:
                if previous_day is None or day > previous_day:
                    previous_day = day

        # This fallback is only defensive; SPY expirations have prior sessions.
        if previous_day is None:
            candidate = expiration_date - timedelta(days=1)
            while candidate.weekday() >= 5:
                candidate -= timedelta(days=1)
            previous_day = candidate

