        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiration = self.Securities[
                    order_event.Symbol
                ].Symbol.ID.Date

                self.Debug(
                    "Entered {0} at fill price {1:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.entry_ticket = None
                self.pending_entry_symbol = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and order_event.Status != OrderStatus.PartiallyFilled:
                self.entry_ticket = None
                self.pending_entry_symbol = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited {0} at fill price {1:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.held_expiration = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        is_assignment = getattr(order_event, "IsAssignment", False)

        if is_assignment:
            self.Debug(
                "Unexpected option exercise or assignment: {0}".format(
                    order_event.Symbol
                )
            )
            self.blocked_date = self.Time.date()
            self._liquidate_spy_equity()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment received.")
        self.blocked_date = self.Time.date()
        self._liquidate_spy_equity()

    def _handle_unexpected_equity_position(self, today):
        quantity = int(self.Portfolio[self.spy.Symbol].Quantity)

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating."
            )
            self.blocked_date = today
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _liquidate_spy_equity(self):
        quantity = int(self.Portfolio[self.spy.Symbol].Quantity)

        if quantity != 0:
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _has_option_holding(self):
        return (
            self.held_symbol is not None and
            self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _cancel_open_exit_order(self):
        if self._exit_order_is_open():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)
            self.exit_ticket = None

    def _is_regular_session_time(self, end_time):
        start = end_time.replace(hour=9, minute=31, second=0, microsecond=0)
        end = end_time.replace(hour=16, minute=0, second=0, microsecond=0)
        return start <= end_time <= end

    def _bucket_end(self, minute_end):
        session_start = minute_end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        elapsed_minutes = int(
            (minute_end - session_start).total_seconds() // 60
        )
        bucket_number = elapsed_minutes // 5
        return session_start + timedelta(minutes=(bucket_number + 1) * 5)

    def _is_immediately_preceding_trading_day(
        self,
        current_date,
        expiration_date
    ):
        candidate = expiration_date - timedelta(days=1)

        while not self._is_spy_trading_day(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _is_spy_trading_day(self, date_value):
        date_time = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        return self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            date_time
        )

    @staticmethod
    def _sma(values, period):
        if len(values) < period:
            return None

        return sum(values[-period:]) / float(period)

