from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            0,
            True
        )
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol

        # Broad enough to include the required expiry and 1% OTM call.
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.entry_blocked_date = None
        self.expiry_blocked_date = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration_start(current_date)

        if self.spy in slice.Bars:
            self._accept_minute_bar(slice.Bars[self.spy], slice)

        if self._has_open_option_position():
            self._evaluate_exit(slice)

    def _accept_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time

        # Only regular-session SPY minute bars are used.
        minutes = local_time.hour * 60 + local_time.minute
        session_open = 9 * 60 + 30
        session_close = 16 * 60

        if minutes < session_open or minutes >= session_close:
            return

        offset = minutes - session_open
        bucket_start = local_time.replace(
            hour=9,
            minute=30 + (offset // 5) * 5,
            second=0,
            microsecond=0
        )

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            self._complete_bucket(slice)

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[local_time] = bar

    def _complete_bucket(self, slice: Slice):
        bucket_start = self.current_bucket_start
        bars = self.current_bucket_bars

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        complete = all(t in bars for t in expected_times)

        # Missing minute data means the five-minute bar is discarded.
        if not complete:
            self.current_bucket_start = None
            self.current_bucket_bars = {}
            return

        close_price = bars[expected_times[-1]].Close
        bucket_end = bucket_start + timedelta(minutes=5)

        self._update_averages(close_price)

        if (
            bucket_end.hour > 9
            or (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14
            or (bucket_end.hour == 14 and bucket_end.minute <= 30)
        ):
            self._evaluate_crossover_entry(
                slice,
                bucket_end,
                float(close_price)
            )

        self.current_bucket_start = None
        self.current_bucket_bars = {}

    def _update_averages(self, close_price: float):
        self.fast_closes.append(close_price)
        self.slow_closes.append(close_price)

        if len(self.fast_closes) == 5:
            current_fast = sum(self.fast_closes) / 5.0
        else:
            current_fast = None

        if len(self.slow_closes) == 20:
            current_slow = sum(self.slow_closes) / 20.0
        else:
            current_slow = None

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
        ):
            self.current_fast = current_fast
            self.current_slow = current_slow
        else:
            self.current_fast = current_fast
            self.current_slow = current_slow

    def _evaluate_crossover_entry(self, slice: Slice, bar_end: datetime, spy_price: float):
        if self.entry_blocked_date == bar_end.date():
            return

        if self._has_open_option_position() or self._entry_order_open():
            return

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.current_fast is not None
            and self.current_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.current_fast > self.current_slow
        ):
            self._select_and_enter(slice, spy_price)

        self.previous_fast = self.current_fast
        self.previous_slow = self.current_slow

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiry at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike meets the 1% OTM requirement."
            )
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        # Time stop at 15:45 on the immediately preceding trading day.
        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and current_date == self._previous_trading_day(expiry_date)
        ):
            self._submit_exit("Expiration-eve 15:45 time stop")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% option profit target")

    def _process_expiration_start(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            if self.expiry_blocked_date != current_date:
                self.expiry_blocked_date = current_date
                self.entry_blocked_date = current_date
                self.Debug(
                    "Unexpected expiration-day holding; submitting liquidation."
                )

            self._submit_exit("Expiration-day liquidation")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None

                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0} at {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

        if bool(getattr(order_event, "IsAssignment", False)) or \
           bool(getattr(order_event, "IsExercise", False)):
            self.entry_blocked_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment detected; "
                "liquidating SPY equity."
            )
            self._handle_unexpected_equity_position()

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.entry_blocked_date = self.Time.date()
        self.Debug(
            "Unexpected assignment event; liquidating SPY equity."
        )
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is not None
            and self.equity_cleanup_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        self.entry_blocked_date = self.Time.date()
        self.equity_cleanup_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise/assignment SPY cleanup"
        )

    def _has_open_option_position(self):
        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Quantity != 0:
                return True

        for holding in self.Portfolio.Values:
            if (
                holding.Quantity != 0
                and holding.Symbol.SecurityType == SecurityType.Option
            ):
                return True

        return False

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()
