                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% option profit target")

    def _process_expiration_start(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            if self.expiry_blocked_date != current_date:
                self.expiry_blocked_date = current_date
                self.entry_blocked_date = current_date
                self.Debug(
                    "Unexpected expiration-day holding; submitting liquidation."
                )

            self._submit_exit("Expiration-day liquidation")

