        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None

                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0} at {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

        if bool(getattr(order_event, "IsAssignment", False)) or \
           bool(getattr(order_event, "IsExercise", False)):
            self.entry_blocked_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment detected; "
                "liquidating SPY equity."
            )
            self._handle_unexpected_equity_position()

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.entry_blocked_date = self.Time.date()
        self.Debug(
            "Unexpected assignment event; liquidating SPY equity."
        )
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is not None
            and self.equity_cleanup_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        self.entry_blocked_date = self.Time.date()
        self.equity_cleanup_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise/assignment SPY cleanup"
        )

    def _has_open_option_position(self):
        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Quantity != 0:
                return True

        for holding in self.Portfolio.Values:
            if (
                holding.Quantity != 0
                and holding.Symbol.SecurityType == SecurityType.Option
            ):
                return True

        return False

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

