            self.bucket_minutes[0].Open,
            max(bar.High for bar in self.bucket_minutes),
            min(bar.Low for bar in self.bucket_minutes),
            self.bucket_minutes[-1].Close,
            sum(bar.Volume for bar in self.bucket_minutes)
        )

