            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))

        selected_contract = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1
        )

        self.Debug(
            "Entry submitted: " + str(selected_contract.Symbol)
        )

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.IsOrderDone(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity == 0:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def ProcessExpiration(self):
        if self.held_symbol is None:
            return

        expiration_date = self.held_symbol.ID.Date.date()

        if self.Time.date() >= expiration_date:
            self.no_entry_today = True

            if (
                self.Portfolio[self.held_symbol].Quantity != 0
                and self.exit_ticket is None
            ):
                self.SubmitExit("expiration safeguard")

            return

        prior_trading_day = expiration_date - timedelta(days=1)

        while not self.IsTradingDay(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")

    def IsTradingDay(self, calendar_date):
        date_time = datetime(
            calendar_date.year,
            calendar_date.month,
            calendar_date.day
        )

        return self.Securities[self.spy].Exchange.Hours.IsDateOpen(date_time)

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )

        self.Debug(
            "Exit submitted (" + reason + "): "
            + str(self.held_symbol)
        )

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position; liquidating immediately"
            )
            self.MarketOrder(self.spy, -quantity)
            self.no_entry_today = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: " + str(order_event.Symbol)
                )

                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected option exercise or assignment; "
            "liquidating SPY equity"
        )

        self.no_entry_today = True

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)

    @staticmethod
    def IsOrderDone(ticket):
        return (
            ticket is None
            or ticket.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )
