        nearest_expiry = min(x.Expiry.date() for x in candidates)
        candidates = [
            x for x in candidates
            if x.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda x: (float(x.Strike), str(x.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def _evaluate_exits(self, slice):
        if self.held_option is None:
            return

        today = self.Time.date()

