class FiveMinuteBarBuilder:
    """Builds complete, New York-aligned five-minute bars from minute TradeBars."""

    def __init__(self, symbol, callback):
        self.symbol = symbol
        self.callback = callback
        self.bucket_start = None
        self.minutes = {}

    def update(self, bar):
        start = bar.Time.replace(second=0, microsecond=0)

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return

        session_start = start.replace(hour=9, minute=30)
        minutes_from_open = int((start - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._finish_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.minutes = {}

        offset = int((start - bucket_start).total_seconds() // 60)
        if 0 <= offset < 5:
            self.minutes[offset] = bar

    def _finish_bucket(self):
        if self.bucket_start is None:
            return

        # Missing minute data means the five-minute bar is not valid.
        if set(self.minutes.keys()) == {0, 1, 2, 3, 4}:
            bars = [self.minutes[i] for i in range(5)]

            consolidated = TradeBar(
                self.bucket_start,
                self.symbol,
                bars[0].Open,
                max(x.High for x in bars),
                min(x.Low for x in bars),
                bars[-1].Close,
                sum(x.Volume for x in bars),
                timedelta(minutes=5)
            )

            self.callback(consolidated)

        self.minutes = {}


class SpyOptionMovingAverageAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
