        if equity_quantity != 0 and self.equity_exit_ticket is None:
            self.Debug(
                f"Unexpected SPY exercise/assignment position: "
                f"{equity_quantity}; liquidating."
            )
            self.equity_exit_ticket = self.MarketOrder(
                self.spy,
                -equity_quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

        # Never intentionally hold an option into expiration.
        if (
            self.held_option is not None
            and self.expiration_date is not None
            and today >= self.expiration_date
        ):
            self.block_entry_date = today
            self._submit_exit("Expiration protection")

        # Evaluate exits on every minute Slice.
        if self.held_option is not None:
            self._evaluate_exits(slice)

        # Build five-minute bars only from actual minute SPY bars.
        if slice.Bars.ContainsKey(self.spy):
            self.bar_builder.update(slice.Bars[self.spy])

    def OnFiveMinuteBar(self, bar: TradeBar):
        end = bar.EndTime
        end_time = end.time()

        # Eligible crossover bars end from 09:45 through 14:30 inclusive.
        if not (
            time(9, 45) <= end_time <= time(14, 30)
        ):
            self._update_averages(bar.Close)
            return

        previous_fast = None
        previous_slow = None

        if len(self.slow_closes) == 20:
            previous_fast = sum(list(self.slow_closes)[-5:]) / 5.0
            previous_slow = sum(self.slow_closes) / 20.0

        self._update_averages(bar.Close)

        if len(self.slow_closes) < 20:
            return

        current_fast = sum(list(self.slow_closes)[-5:]) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if self.block_entry_date == self.Time.date():
            return

        if self.held_option is not None or self._entry_order_open():
            return

        if self.current_slice is None:
            return

        if not self.current_slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: no current SPY price.")
            return

        spy_price = float(self.current_slice.Bars[self.spy].Close)
        self._try_enter(self.current_slice, spy_price)

    def _update_averages(self, close):
        self.fast_closes.append(float(close))
        self.slow_closes.append(float(close))

    def _try_enter(self, slice, spy_price):
        chain = None

