from collections import deque
from datetime import datetime, date, time, timedelta
import math


class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        local_now = self.Time
        current_date = local_now.date()

        self._handle_unexpected_equity_position(current_date)
        self._handle_expiration_processing(current_date)

        if self.held_symbol is not None:
            self._evaluate_position_exit(data)

        if self.spy.Symbol in data.Bars:
            spy_bar = data.Bars[self.spy.Symbol]
            self._process_minute_bar(spy_bar, data)

    def _process_minute_bar(self, minute_bar: TradeBar, data: Slice):
        local_end = minute_bar.EndTime

        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        current_minutes = local_end.hour * 60 + local_end.minute
        if current_minutes < 570 or current_minutes > 960:
            return

        bucket_end_minutes = 570 + (
            int(math.ceil((current_minutes - 570) / 5.0)) * 5
        )

        bucket_end_hour = bucket_end_minutes // 60
        bucket_end_minute = bucket_end_minutes % 60
        bucket_end = datetime(
            local_end.year,
            local_end.month,
            local_end.day,
            bucket_end_hour,
            bucket_end_minute
        )

        bucket_key = (local_end.date(), bucket_end)

        if self.bucket_end is not None and bucket_key != (
            self.bucket_date,
            self.bucket_end
        ):
            self._discard_incomplete_bucket()

        if self.bucket_end is None:
            self.bucket_date = local_end.date()
            self.bucket_end = bucket_end
            self.bucket_bars = []
            self.bucket_close = None

        if bucket_key != (self.bucket_date, self.bucket_end):
            return

        self.bucket_bars.append(minute_bar)
        self.bucket_close = minute_bar.Close

        if local_end == self.bucket_end:
            if len(self.bucket_bars) == 5:
                consolidated_bar = TradeBar(
                    self.bucket_end - timedelta(minutes=5),
                    self.spy.Symbol,
                    self.bucket_bars[0].Open,
                    max(x.High for x in self.bucket_bars),
                    min(x.Low for x in self.bucket_bars),
                    self.bucket_bars[-1].Close,
                    sum(x.Volume for x in self.bucket_bars),
                    timedelta(minutes=5)
                )
                consolidated_bar.EndTime = self.bucket_end
                self._on_five_minute_bar(consolidated_bar, data)
            else:
                self.Debug(
                    "Skipped incomplete SPY five-minute interval ending "
                    f"{self.bucket_end:%Y-%m-%d %H:%M}"
                )

            self.bucket_date = None
            self.bucket_end = None
            self.bucket_bars = []
            self.bucket_close = None

    def _discard_incomplete_bucket(self):
        if self.bucket_end is not None and self.bucket_bars:
            self.Debug(
                "Skipped incomplete SPY five-minute interval ending "
                f"{self.bucket_end:%Y-%m-%d %H:%M}"
            )

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_close = None

    def _on_five_minute_bar(self, bar: TradeBar, data: Slice):
        fast = None
        slow = None

        if len(self.closes) >= 5:
            fast = sum(list(self.closes)[-5:]) / 5.0

        if len(self.closes) >= 20:
            slow = sum(self.closes) / 20.0

        bullish_crossover = (
            fast is not None and
            slow is not None and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow
        self.closes.append(float(bar.Close))

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter_option(data, bar.Close)

    def _try_enter_option(self, data: Slice, spy_price: float):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = data.OptionChains
        if self.spy_option.Symbol not in chains:
            self.Debug("Skipped entry: current Slice has no SPY option chain.")
            return

        chain = chains[self.spy_option.Symbol]
        contracts = self._contracts_from_chain(chain)

        minimum_expiry = current_date + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at the selected expiration."
            )
            return

        candidates.sort(
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected_expiry} strike={selected.Strike}"
        )

    def _evaluate_position_exit(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        held_contract = self._find_contract(data, self.held_symbol)

        if held_contract is not None:
            bid = float(held_contract.BidPrice)
            ask = float(held_contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("50% profit target")

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()
            previous_trading_date = self._previous_trading_date(expiry_date)

            if (
                self.Time.date() == previous_trading_date and
                self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self, current_date: date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing liquidation")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {reason} symbol={self.held_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.held_symbol} "
                        f"price={self.entry_price:.4f}"
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Entry order canceled or invalid.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {self.exit_ticket.Tag} "
                        f"symbol={self.exit_ticket.Symbol}"
                    )
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None and
            order_event.OrderId == self.equity_liquidation_ticket.OrderId and
            order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.equity_liquidation_ticket = None

    def _handle_unexpected_equity_position(self, current_date: date):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity == 0:
            return

        self.no_entry_date = current_date

        if (
            self.equity_liquidation_ticket is None or
            not self._ticket_is_open(self.equity_liquidation_ticket)
        ):
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected: "
                f"quantity={quantity}. Liquidating immediately."
            )
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _find_contract(self, data: Slice, symbol: Symbol):
        for chain in data.OptionChains.Values:
            for contract in self._contracts_from_chain(chain):
                if contract.Symbol == symbol:
                    return contract
        return None

    @staticmethod
    def _contracts_from_chain(chain):
        if hasattr(chain.Contracts, "Values"):
            return list(chain.Contracts.Values)
        return list(chain.Contracts.values())

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_date(self, expiry_date: date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while True:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if exchange_hours.IsDateOpen(candidate_datetime):
                return candidate

            candidate -= timedelta(days=1)
