from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishOptionCrossover(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        self.spy = self.add_equity("SPY", Resolution.MINUTE)
        self.spy.set_data_normalization_mode(DataNormalizationMode.RAW)
        self.spy_symbol = self.spy.symbol

        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option_symbol = self.option.symbol

        # Broad universe: weekly/monthly contracts, sufficient expirations
        # and strikes around the underlying price.
        self.option.set_filter(
            lambda universe: universe
                .include_weeklys()
                .strikes(-200, 200)
                .expiration(0, 730)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_key = None
        self.current_bucket = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_block_date = None
        self.last_time_stop_date = None
        self.equity_liquidation_pending = False

    def on_data(self, slice: Slice):
        algorithm_date = self.time.date()

        # Immediately remove unexpected SPY equity created by exercise/assignment.
        spy_quantity = self.portfolio[self.spy_symbol].quantity
        if spy_quantity != 0 and not self.equity_liquidation_pending:
            self.debug(
                f"Unexpected SPY equity position from exercise/assignment: "
                f"{spy_quantity}; liquidating."
            )
            self.market_order(
                self.spy_symbol,
                -spy_quantity,
                tag="Unexpected exercise/assignment liquidation"
            )
            self.equity_liquidation_pending = True
            self.expiration_block_date = algorithm_date

        if spy_quantity == 0:
            self.equity_liquidation_pending = False

        # Process the held option on every minute Slice.
        if self.held_symbol is not None:
            expiry_date = self._expiry_date(self.held_symbol)

            # Never intentionally hold through expiration.
            if expiry_date is not None and algorithm_date >= expiry_date:
                self.expiration_block_date = algorithm_date
                self._submit_exit("Expiration safeguard")
            else:
                self._evaluate_option_exit(slice, expiry_date)

        # Build five-minute bars directly from actual minute TradeBars.
        minute_bar = slice.bars.get(self.spy_symbol)
        if minute_bar is None:
            return

        completed_bar = self._update_five_minute_bar(minute_bar)
        if completed_bar is None:
            return

        self._process_completed_bar(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar):
        end_time = minute_bar.end_time
        local_date = end_time.date()
        local_time = end_time.time()

        # Regular-session minute bars only.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return None

        minute = end_time.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = time(bucket_end_minute % 60, 0)

        bucket_key = (local_date, bucket_end)

        if self.current_bucket_key != bucket_key:
            # An incomplete prior bucket is discarded. No synthetic bar.
            self.current_bucket_key = bucket_key
            self.current_bucket = {}

        self.current_bucket[end_time] = minute_bar

        if bucket_end_minute == 0 or len(self.current_bucket) != 5:
            return None

        expected_times = [
            datetime.combine(
                local_date,
                time(bucket_end_minute - offset, 0)
            )
            for offset in range(4, -1, -1)
        ]

        if any(expected not in self.current_bucket for expected in expected_times):
            self.current_bucket = {}
            return None

        bars = [self.current_bucket[value] for value in expected_times]
        self.current_bucket = {}

        return TradeBar(
            self.spy_symbol,
            bars[0].time,
            bars[-1].end_time,
            bars[0].open,
            max(bar.high for bar in bars),
            min(bar.low for bar in bars),
            bars[-1].close,
            sum(bar.volume for bar in bars),
            timedelta(minutes=5)
        )

    def _process_completed_bar(self, bar, slice):
        close = float(bar.close)

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        fast = sum(self.fast_window) / 5.0
        slow = sum(self.slow_window) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end_time = bar.end_time.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if not bullish_crossover or not eligible_time:
            return

        algorithm_date = self.time.date()

        if self.expiration_block_date == algorithm_date:
            return

        if self.held_symbol is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        self._select_and_enter(slice, close, algorithm_date)

    def _select_and_enter(self, slice, spy_price, algorithm_date):
        chain = slice.option_chains.get(self.option_symbol)

        if chain is None:
            self.debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        candidates = []

        for contract in chain.contracts.values():
            expiry = self._expiry_date(contract.symbol)
            if expiry is None or expiry < minimum_expiry:
                continue

            if contract.right != OptionRight.CALL:
                continue

            if float(contract.strike) < 1.01 * spy_price:
                continue

            candidates.append(contract)

        if not candidates:
            self.debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(self._expiry_date(c.symbol) for c in candidates)
        same_expiry = [
            c for c in candidates
            if self._expiry_date(c.symbol) == nearest_expiry
        ]

        selected = min(
            same_expiry,
            key=lambda c: (float(c.strike), str(c.symbol))
        )

        self.add_option_contract(selected.symbol, Resolution.MINUTE)

        self.entry_symbol = selected.symbol
        self.entry_ticket = self.market_order(
            selected.symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.debug(
            f"Entry submitted: {selected.symbol}, "
            f"expiry={nearest_expiry}, strike={selected.strike}"
        )

    def _evaluate_option_exit(self, slice, expiry_date):
        algorithm_date = self.time.date()
        current_time = self.time.time()

        # Scheduled time stop on the trading day immediately before expiry.
        if (
            expiry_date is not None
            and current_time >= time(15, 45)
            and self._is_immediately_prior_trading_day(
                algorithm_date, expiry_date
            )
            and self.last_time_stop_date != algorithm_date
        ):
            self.last_time_stop_date = algorithm_date
            self._submit_exit("Pre-expiration time stop")
            return

        # A target test requires a strictly positive current bid and ask.
        bid, ask = self._current_bid_ask(slice, self.held_symbol)
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50% profit target")

    def _current_bid_ask(self, slice, symbol):
        quote = slice.quote_bars.get(symbol)
        if quote is not None and quote.bid is not None and quote.ask is not None:
            return float(quote.bid.close), float(quote.ask.close)

        for chain in slice.option_chains.values():
            contract = chain.contracts.get(symbol)
            if contract is not None:
                return (
                    float(contract.bid_price),
                    float(contract.ask_price)
                )

        return None, None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.cancel("Exit requested before entry completion")
            return

        quantity = self.portfolio[self.held_symbol].quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket = None

        self.exit_ticket = self.market_order(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def on_order_event(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
        ):
            if order_event.status == OrderStatus.FILLED:
                self.held_symbol = order_event.symbol
                self.entry_price = float(order_event.fill_price)
                self.entry_ticket = None
                self.debug(
                    f"Entry filled: {self.held_symbol}; "
                    f"price={self.entry_price:.4f}"
                )
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.order_id == self.exit_ticket.order_id
        ):
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"Exit filled: {order_event.symbol}; "
                    f"price={order_event.fill_price:.4f}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.exit_ticket = None

    def on_assignment_order_event(self, assignment_event):
        self.debug(
            f"Unexpected option assignment/exercise event: "
            f"{assignment_event.symbol}"
        )

        quantity = self.portfolio[self.spy_symbol].quantity
        if quantity != 0 and not self.equity_liquidation_pending:
            self.market_order(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise/assignment liquidation"
            )
            self.equity_liquidation_pending = True
            self.expiration_block_date = self.time.date()

    def _expiry_date(self, symbol):
        try:
            return symbol.id.date.date()
        except Exception:
            try:
                return symbol.expiry.date()
            except Exception:
                return None

    def _is_immediately_prior_trading_day(self, current_date, expiry_date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
            if self.securities[self.spy_symbol].exchange.hours.is_date_open(
                candidate
            ):
                return False
            candidate += timedelta(days=1)

        return candidate == expiry_date

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.CANCEL_PENDING
        )
