        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.current_bucket is None:
            self.current_bucket = bucket_start
        elif bucket_start != self.current_bucket:
            self._discard_bucket()
            self.current_bucket = bucket_start

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            completed_bar = self._build_consolidated_bar(self.bucket_bars)
            self._discard_bucket()
            self._evaluate_completed_bar(completed_bar, slice)

    def _build_consolidated_bar(self, bars):
        first = bars[0]
        last = bars[-1]

        return TradeBar(
            first.Time,
            self.spy.Symbol,
            first.Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            last.Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

    def _discard_bucket(self):
        self.current_bucket = None
        self.bucket_bars = []

    def _evaluate_completed_bar(self, bar: TradeBar, slice: Slice):
        previous_fast = None
        previous_slow = None

        if len(self.close_window) >= 20:
            previous_fast = sum(self.close_window[-5:]) / 5.0
            previous_slow = sum(self.close_window[-20:]) / 20.0

        self.close_window.append(float(bar.Close))
        if len(self.close_window) > 20:
            self.close_window.pop(0)

        if len(self.close_window) < 20:
            return

        current_fast = sum(self.close_window[-5:]) / 5.0
        current_slow = sum(self.close_window[-20:]) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
