            self.Debug("Skipped entry: no qualifying call contract at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.held_option = selected.Symbol
        self.entry_price = None

        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                expiration_date,
                selected.Strike
            )
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiration_date = self.held_option.ID.Date.date()

        if self.Time.date() >= expiration_date:
            self.no_entry_date = self.Time.date()
            self._cancel_entry_if_open()
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        contract = None
        if slice.OptionChains.ContainsKey(self.option.Symbol):
            for candidate in slice.OptionChains[self.option.Symbol]:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
