        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not (eligible_start <= bar_end.time() <= eligible_end):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None:
            return

        if self._has_option_holding():
            return

        self._enter_option(slice, float(bar.Close))

    def _enter_option(self, slice: Slice, spy_price: float):
        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        current_date = self.Time.date()

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiration_date = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiration_date
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.held_option = selected.Symbol
        self.entry_price = None

        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                expiration_date,
                selected.Strike
            )
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiration_date = self.held_option.ID.Date.date()

        if self.Time.date() >= expiration_date:
            self.no_entry_date = self.Time.date()
            self._cancel_entry_if_open()
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)
