            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        contract = None
        if slice.OptionChains.ContainsKey(self.option.Symbol):
            for candidate in slice.OptionChains[self.option.Symbol]:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            return

        self.exit_order_id = self.MarketOrder(
            self.held_option,
            -quantity
        ).OrderId

        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:. fyra}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )
                self.entry_order_id = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Margin
            ):
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Margin
            ):
                self.exit_order_id = None

        if (
            self.spy_liquidation_order_id is not None
            and order_event.OrderId == self.spy_liquidation_order_id
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Margin
            )
        ):
            self.spy_liquidation_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug("Unexpected exercise or assignment detected.")
        self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        self.spy_liquidation_order_id = self.MarketOrder(
            self.spy.Symbol,
            -quantity
        ).OrderId

    def _cancel_entry_if_open(self):
        if self.entry_order_id is not None:
            self.Transactions.CancelOrder(self.entry_order_id)
            self.entry_order_id = None

    def _has_option_holding(self):
        return any(
            security.Invested
            and security.Symbol.SecurityType == SecurityType.Option
            for security in self.Portfolio.Values
        )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)

        while not self.spy.Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

