        return self.IsOrderOpen(self.entry_ticket)

    def IsExitOrderOpen(self):
        return self.IsOrderOpen(self.exit_ticket)

    @staticmethod
    def IsOrderOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]
