                candidate.month,
                candidate.day
            )

            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
                candidate_datetime
            ):
                return current_date == candidate

            candidate -= timedelta(days=1)

        return False

    def IsEntryOrderOpen(self):
        return self.IsOrderOpen(self.entry_ticket)

    def IsExitOrderOpen(self):
        return self.IsOrderOpen(self.exit_ticket)

