from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import deque


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)

        # Current five-minute aggregation state.
        self.bucket_key = None
        self.bucket_bars = {}

        self.held_option = None
        self.entry_order = None
        self.entry_price = None
        self.exit_order = None

        self.blocked_entry_date = None
        self.equity_liquidation_order = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        # Process option exits before considering any new entry.
        self._process_option_exits(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        bar_end = completed_bar["end"]
        close = completed_bar["close"]

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (
            (bar_end.hour == 9 and bar_end.minute >= 45) or
            (10 <= bar_end.hour <= 13) or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        ):
            return

        if self.blocked_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_order is not None and self._order_is_open(self.entry_order):
            return

        self._try_enter(slice, close, current_date)

    def _update_five_minute_bar(self, minute_bar):
        start = minute_bar.Time

        if start.hour < 9 or start.hour >= 16:
            return None

        if start.hour == 9 and start.minute < 30:
            return None

        bucket_minute = (start.minute // 5) * 5
        key = datetime(
            start.year,
            start.month,
            start.day,
            start.hour,
            bucket_minute
        )

        if self.bucket_key != key:
            self.bucket_key = key
            self.bucket_bars = {}

        self.bucket_bars[start.minute] = minute_bar

        expected_minutes = set(range(bucket_minute, bucket_minute + 5))
        if not expected_minutes.issubset(set(self.bucket_bars.keys())):
            return None

        bars = [self.bucket_bars[m] for m in range(bucket_minute, bucket_minute + 5)]

        if any(
            bars[i].Time.minute != bucket_minute + i
            for i in range(5)
        ):
            return None

        completed = {
            "end": key + timedelta(minutes=5),
            "close": bars[-1].Close
        }

        self.bucket_bars = {}
        return completed

    def _try_enter(self, slice, spy_price, current_date):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        contract = candidates[0]

        self.entry_order = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol.Value}, "
            f"expiry {selected_expiry}, strike {contract.Strike}"
        )

    def _process_option_exits(self, slice: Slice):
        if self.held_option is None:
            return

        current_date = self.Time.date()
        expiry_date = self.held_option.Expiry.date()

        # Never intentionally hold through expiration.
        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        # Time stop on the trading day immediately preceding expiration.
        prior_trading_day = self._prior_trading_day(expiry_date)

        if (
            current_date == prior_trading_day and
            self.Time.hour == 15 and
            self.Time.minute == 45
        ):
            self._submit_exit("expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_option.Symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None and
            midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_order is not None and self._order_is_open(self.exit_order):
            self.exit_order.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        self.exit_order = self.MarketOrder(
            self.held_option.Symbol,
            -quantity
        )
        self.Debug(
            f"Exit submitted: {self.held_option.Symbol.Value}, reason: {reason}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order is not None and
                order_event.OrderId == self.entry_order.OrderId
