        contract = candidates[0]

        self.entry_order = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol.Value}, "
            f"expiry {selected_expiry}, strike {contract.Strike}"
        )

