    def _get_bucket_start(minute_start):
        session_start = datetime(
            minute_start.year,
            minute_start.month,
            minute_start.day,
            9,
            30
        )

        elapsed_minutes = int(
            (minute_start - session_start).total_seconds() // 60
        )
        bucket_offset = (elapsed_minutes // 5) * 5

        return session_start + timedelta(minutes=bucket_offset)
