from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishOptionAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.current_bucket_start = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        # An unexpected SPY equity position can only result from exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {spy_quantity}; "
                "liquidating immediately."
            )
            self.MarketOrder(self.spy, -spy_quantity, tag="Unexpected exercise/assignment cleanup")
            self.expiration_block_date = self.Time.date()

        self._process_held_option_exits(slice)

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.expiration_block_date == self.Time.date():
            return

        minute_bar = self._get_spy_bar(slice)
        if minute_bar is None:
            return

        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            self.current_bucket_start = None
            self.current_bucket_bars = []
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        # A bucket must begin exactly on a five-minute boundary.
        if self.current_bucket_start is None:
            if bar_time.minute % 5 != 0:
                return
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = [bar]
            return

        expected_time = self.current_bucket_bars[-1].Time + timedelta(minutes=1)

        if bar_time != expected_time or bucket_start != self.current_bucket_start:
            self.current_bucket_start = None
            self.current_bucket_bars = []

            if bar_time.minute % 5 == 0:
                self.current_bucket_start = bucket_start
                self.current_bucket_bars = [bar]
            return

        self.current_bucket_bars.append(bar)

        if len(self.current_bucket_bars) != 5:
            return

        five_minute_end = self.current_bucket_start + timedelta(minutes=5)
        close = self.current_bucket_bars[-1].Close

        self.current_bucket_start = None
        self.current_bucket_bars = []

        self._process_five_minute_close(five_minute_end, close, slice)

    def _process_five_minute_close(self, bar_end: datetime, close: float, slice: Slice):
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        end_time = bar_end.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call and
                    expiry_date >= minimum_expiry
                ):
                    eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no eligible call expiration or contract.")
            return

        nearest_expiry = min(
            contract.Expiry.date()
            for contract in eligible_contracts
        )

        minimum_strike = float(spy_price) * 1.01

        strike_candidates = [
            contract
            for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry and
               contract.Strike >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no contract meets the strike rule.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration={nearest_expiry}; strike={selected.Strike}"
        )

    def _process_held_option_exits(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        security = self.Securities[self.held_option]
        expiration_date = security.Symbol.ID.Date.date()

        # Never intentionally hold through expiration.
        if self.Time.date() >= expiration_date:
            self.expiration_block_date = self.Time.date()
            self._submit_exit("Expiration liquidation")
            return

        # Trading day immediately preceding expiration.
        previous_trading_day = self._previous_trading_day(expiration_date)

        if (
            self.Time.date() == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        midpoint = self._current_option_midpoint(slice, self.held_option)

        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_option}; reason={reason}")

    def _current_option_midpoint(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

                return None

        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"Entry filled: {self.held_option}; "
                    f"price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                if (
                    self.held_option is not None and
                    self.Portfolio[self.held_option].Quantity == 0
                ):
                    self.Debug(f"Exit filled: {self.held_option}")
                    self.held_option = None
                    self.entry_price = None
                    self.entry_ticket = None
                    self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_event: AssignmentEvent):
        self.Debug(
            f"Unexpected option exercise/assignment: {assignment_event.Symbol}; "
            f"quantity={assignment_event.Quantity}"
        )

        self.expiration_block_date = self.Time.date()

        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                tag="Unexpected exercise/assignment cleanup"
            )

    def _get_spy_bar(self, slice: Slice):
        if self.spy in slice.Bars:
            return slice.Bars[self.spy]
        return None

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        previous = exchange_hours.GetPreviousTradingDay(
            datetime.combine(date_value, time(0, 0))
        )
        return previous.date()

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit condition")

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
