from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_bars = {}

        self.held_option = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Process expiration-day liquidation before any possible entry.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_block_date = current_date
                self.SubmitOptionExit("expiration processing")
            elif self.Time >= self._day_before_expiration_at_1545(
                expiry_date
            ):
                self.SubmitOptionExit("expiration time stop")

        # Evaluate the profit target on every minute Slice.
        self.EvaluateProfitTarget(slice)

        # Immediately liquidate unexpected SPY equity created by exercise
        # or assignment.
        self.HandleUnexpectedEquity(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        minute_bar = slice.Bars[self.spy]
        local_time = self.Time

        if not self._is_regular_session_minute(local_time):
            self._flush_bucket()
            return

        bucket_start = self._bucket_start(local_time)

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self._flush_bucket()
            self.bucket_start = bucket_start

        self.bucket_bars[local_time] = minute_bar

        # A five-minute bar ending at 09:35 is built from 09:30-09:34.
        if local_time.minute % 5 == 4:
            completed = self._build_completed_bar()
            self.bucket_bars = {}
            self.bucket_start = None

            if completed is not None:
                self.OnFiveMinuteBar(completed, slice)

    def OnFiveMinuteBar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous_closes = self.closes[:-1]
        current_closes = self.closes

        previous_fast = sum(previous_closes[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous_closes[-self.slow_period:]) / self.slow_period
        current_fast = sum(current_closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(current_closes[-self.slow_period:]) / self.slow_period

        crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = self.Time
        eligible_time = (
            datetime(2000, 1, 1, 9, 45).time()
            <= bar_end.time()
            <= datetime(2000, 1, 1, 14, 30).time()
        )

        if crossover and eligible_time:
            self.TryEnter(slice, bar.Close)

    def TryEnter(self, slice: Slice, spy_price: float):
        if self.expiration_block_date == self.Time.date():
            return

        if self.entry_order_id is not None:
            return

        if self.held_option is not None:
            holding = self.Portfolio[self.held_option]
            if holding.Invested:
                return

        for security in self.Securities.Values:
            if security.Symbol.SecurityType == SecurityType.Option:
                if self.Portfolio[security.Symbol].Invested:
                    return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Symbol.ID.OptionStyle == OptionStyle.American
                    and contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        selected = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not selected:
            self.Debug(
                "Skipped selection: no qualifying contract at selected expiry"
            )
            return

        selected.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        contract = selected[0]

        self.held_option = contract.Symbol
        self.entry_price = None
        ticket = self.MarketOrder(contract.Symbol, 1, tag="Strategy entry")
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {contract.Symbol} "
            f"expiry={selected_expiry} strike={contract.Strike}"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested or self.exit_order_id is not None:
            return

        quote = self._find_contract_in_slice(slice, self.held_option)
        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("50% profit target")

    def SubmitOptionExit(self, reason: str):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self.exit_order_id is not None:
            existing = self.Transactions.GetOrderTicket(self.exit_order_id)
            if existing is not None:
                status = existing.Status
                if status not in [
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    existing.Cancel("Replaced by liquidation")

        ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=f"Strategy exit: {reason}"
        )
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason}")

    def HandleUnexpectedEquity(self, slice: Slice):
        spy_holding = self.Portfolio[self.spy]

        if not spy_holding.Invested:
            return

        assignment_detected = False

        for event in self.Transactions.GetOrderEvents():
            if event.Symbol == self.spy:
                if getattr(event, "IsAssignment", False):
                    assignment_detected = True

        if assignment_detected or self.expiration_block_date == self.Time.date():
            self.expiration_block_date = self.Time.date()
            self.MarketOrder(
                self.spy,
                -spy_holding.Quantity,
                tag="Unexpected exercise/assignment liquidation"
            )
            self.Debug(
                "Unexpected exercise or assignment: SPY equity liquidated"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol} "
                    f"price={self.entry_price}"
                )
                self.entry_order_id = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.Debug("Entry order canceled or invalid")
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_order_id = None

        if getattr(order_event, "IsAssignment", False):
            self.expiration_block_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment event: "
                f"{order_event.Symbol}"
            )

    def _build_completed_bar(self):
        if self.bucket_start is None:
            return None

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(time not in self.bucket_bars for time in expected_times):
            return None

        bars = [self.bucket_bars[time] for time in expected_times]

        return TradeBar(
            self.bucket_start,
            self.spy,
            float(bars[0].Open),
            max(float(bar.High) for bar in bars),
            min(float(bar.Low) for bar in bars),
            float(bars[-1].Close),
            sum(int(bar.Volume) for bar in bars),
            timedelta(minutes=5)
        )

    def _flush_bucket(self):
        self.bucket_bars = {}
        self.bucket_start = None

    @staticmethod
    def _bucket_start(local_time: datetime):
        offset = (local_time.minute - 30) % 5
        return local_time.replace(
            minute=local_time.minute - offset,
            second=0,
            microsecond=0
        )

    @staticmethod
    def _is_regular_session_minute(local_time: datetime):
        return (
            local_time.weekday() < 5
            and datetime(2000, 1, 1, 9, 30).time()
            <= local_time.time()
            < datetime(2000, 1, 1, 16, 0).time()
        )

    def _day_before_expiration_at_1545(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        return datetime.combine(
            candidate,
            datetime.min.time()
        ).replace(hour=15, minute=45)

