from AlgorithmImports import *
from datetime import datetime, date, time, timedelta


class SpyBullishOptionCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = []
        self.slow_closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_open = False
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.assignment_warning_logged = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration()
        self._evaluate_exits(slice)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is not None:
            self._accept_minute_bar(bar, slice)

    def _accept_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        bar_date = end.date()
        minute_of_day = end.hour * 60 + end.minute

        # Regular SPY session only.
        if minute_of_day < 570 or minute_of_day > 960:
            return

        # A five-minute bar ending at 09:35 contains 09:31 through 09:35.
        bucket_index = (minute_of_day - 571) // 5
        bucket_end_minute = 575 + bucket_index * 5
        bucket_end = datetime.combine(
            bar_date,
            time(bucket_end_minute // 60, bucket_end_minute % 60)
        )

        if self.bucket_date != bar_date or self.bucket_end != bucket_end:
            self._finalize_bucket(slice)

            self.bucket_date = bar_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        minute_key = (end.hour, end.minute)
        if minute_key in self.bucket_bars:
            return

        self.bucket_bars[minute_key] = bar

        if minute_of_day == bucket_end_minute:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_end is None or not self.bucket_bars:
            return

        # Do not synthesize a bar when any minute is missing.
        expected = []
        end_minute = self.bucket_end.hour * 60 + self.bucket_end.minute
        for minute in range(end_minute - 4, end_minute + 1):
            expected.append((minute // 60, minute % 60))

        if any(key not in self.bucket_bars for key in expected):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[key] for key in expected]
        close = bars[-1].Close

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) > 5:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)

        fast = None
        slow = None

        if len(self.fast_closes) == 5 and len(self.slow_closes) == 20:
            fast = sum(self.fast_closes) / 5.0
            slow = sum(self.slow_closes) / 20.0

        eligible_time = (
            time(9, 45) <= self.bucket_end.time() <= time(14, 30)
        )

        bullish_cross = (
            fast is not None
            and slow is not None
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        if bullish_cross and eligible_time:
            self._try_entry(slice, close)

        if fast is not None and slow is not None:
            self.previous_fast = fast
            self.previous_slow = slow

        self.bucket_bars = {}

    def _try_entry(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.entry_order_open or self.held_symbol is not None:
            return

        for security in self.Securities.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and security.Holdings.Quantity != 0
            ):
                return

        chain = None
        for key, candidate in slice.OptionChains.items():
            if key == self.option_symbol or candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("SKIP: no option chain on crossover")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug("SKIP: no expiration at least 7 calendar days out")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("SKIP: no qualifying call at selected expiration")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_open = True

    def _evaluate_exits(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._has_open_exit_order():
            return

        held_contract = None
        for _, chain in slice.OptionChains.items():
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    held_contract = contract
                    break
            if held_contract is not None:
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0 or self._has_open_exit_order():
            return

        if self.entry_ticket is not None and self.entry_order_open:
            return

        self._cancel_exit_order()

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "EXIT submitted: {} {}".format(self.held_symbol, reason)
        )

    def _has_open_exit_order(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        }

    def _cancel_exit_order(self):
        if self._has_open_exit_order():
            self.exit_ticket.Cancel("Superseded by another exit")

    def _is_pre_expiration_trading_day(self, current_date, expiry_date):
        exchange_hours = self.Securities[self.held_symbol].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while candidate >= current_date:
            if exchange_hours.IsDateOpen(candidate):
                return candidate == current_date
            candidate -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(order_event.Message).lower()
        if "exercise" in message or "assign" in message:
            self.Debug("UNEXPECTED exercise/assignment: {}".format(
                order_event.Message
            ))

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_order_open = False
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "ENTRY filled: {} at {:.4f}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                elif order_event.Status in {
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                }:
                    self.entry_order_open = False
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "EXIT filled: {} at {:.4f}".format(
                            self.exit_ticket.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in {
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                }:
                    self.exit_ticket = None

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0:
            if not self.assignment_warning_logged:
                self.Debug(
                    "UNEXPECTED SPY equity position; liquidating immediately"
                )
                self.assignment_warning_logged = True

            self.Liquidate(
                self.spy.Symbol,
                "Unexpected exercise or assignment handling"
            )
        else:
            self.assignment_warning_logged = False
