        if quantity <= 0:
            return

        self._exit_ticket = self.market_order(
            self._held_symbol,
            -quantity,
            tag=reason
        )

        self.debug(f"Exit submitted: {self._held_symbol} ({reason})")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status != OrderStatus.FILLED:
            return

        if (
            self._entry_ticket is not None
            and order_event.order_id == self._entry_ticket.order_id
            and order_event.fill_quantity > 0
        ):
            self._held_symbol = order_event.symbol
            self._entry_price = float(order_event.fill_price)

            self.debug(
                f"Entry filled: {self._held_symbol} "
                f"price={self._entry_price:.4f}"
            )

        elif (
            self._exit_ticket is not None
            and order_event.order_id == self._exit_ticket.order_id
        ):
            if self._held_symbol is not None:
                remaining = self.portfolio[self._held_symbol].quantity

                if remaining <= 0:
                    self.debug(f"Exit filled: {self._held_symbol}")
                    self._held_symbol = None
                    self._entry_price = None
                    self._exit_ticket = None

    def on_assignment_order_event(self, assignment_event):
        self._blocked_date = self.time.date()
        self.debug("Unexpected option assignment/exercise detected.")

        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self._spy].quantity

        if quantity == 0:
            return

        self._blocked_date = self.time.date()

        if (
            self._equity_liquidation_ticket is None
            or not self._is_open_ticket(self._equity_liquidation_ticket)
        ):
            self._equity_liquidation_ticket = self.market_order(
                self._spy,
                -quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

            self.debug(
                f"Unexpected SPY equity position liquidated: quantity={quantity}"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.securities[self._spy].exchange.hours

        while not exchange_hours.is_date_open(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _is_open_ticket(ticket):
        return ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )
