from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time as dt_time


class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        equity = self.add_equity("SPY", Resolution.MINUTE)
        equity.set_data_normalization_mode(DataNormalizationMode.RAW)
        self.spy = equity.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        self.option_canonical = option.symbol

        # Broad universe: all strikes within a wide range and expirations
        # from today through two years out.
        option.set_filter(
            -1000,
            1000,
            timedelta(days=0),
            timedelta(days=730)
        )

        self.closes = deque(maxlen=20)
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_reason = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

    def on_data(self, slice: Slice):
        now = self.time
        current_date = now.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(now)

        spy_bar = slice.bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        self._evaluate_profit_target(slice)
        self._handle_time_stop()

    def _process_minute_bar(self, minute_bar, slice: Slice):
        local_time = self.time.replace(second=0, microsecond=0)

        if not (
            dt_time(9, 31) <= local_time.time() <= dt_time(16, 0)
        ):
            return

        end_minute = ((local_time.minute // 5) + 1) * 5
        bucket_end = local_time.replace(
            minute=end_minute % 60,
            second=0,
            microsecond=0
        )

        if end_minute >= 60:
            bucket_end = local_time.replace(
                hour=local_time.hour + 1,
                minute=0,
                second=0,
                microsecond=0
            )

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_time] = minute_bar

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.bucket_bars for t in expected):
            return

        bars = [self.bucket_bars[t] for t in expected]

        # Require five contiguous actual minute bars. No filling or synthesis.
        if any(
            bars[i].end_time - bars[i - 1].end_time != timedelta(minutes=1)
            for i in range(1, len(bars))
        ):
            self.bucket_bars = {}
            return

        consolidated = TradeBar(
            bars[0].time,
            self.spy,
            timedelta(minutes=5),
            bars[0].open,
            max(x.high for x in bars),
            min(x.low for x in bars),
            bars[-1].close,
            sum(x.volume for x in bars)
        )

        self.bucket_bars = {}
        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        close = float(bar.close)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 5:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0

        if len(self.closes) >= 20:
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        end_time = self.time.time()

        if not (dt_time(9, 45) <= end_time <= dt_time(14, 30)):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.entry_ticket is not None:
            return

        if self._has_option_position():
            return

        chain = slice.option_chains.get(self.option_canonical)
        if chain is None:
            self.debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract
            for contract in chain
            if contract.symbol.id.option_right == OptionRight.CALL
            and contract.symbol.id.date.date() >= minimum_expiry
        ]

        if not contracts:
            self.debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = min(
            contract.symbol.id.date.date()
            for contract in contracts
        )

        strike_floor = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.symbol.id.date.date() == selected_expiry
            and contract.symbol.id.strike_price >= strike_floor
        ]

        if not candidates:
            self.debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.symbol.id.strike_price,
                str(contract.symbol)
            )
        )

        self.entry_symbol = selected.symbol
        self.entry_price = None
        self.exit_ticket = None
        self.exit_reason = None

        self.entry_ticket = self.market_order(selected.symbol, 1)

        self.debug(
            f"Entry submitted: {selected.symbol}, "
            f"expiration={selected_expiry}, "
            f"strike={selected.symbol.id.strike_price}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_symbol is None:
            return

        if self.entry_price is None:
            return

        if not self._has_option_position():
            return

        if self.exit_ticket is not None:
            return

