        if chain is None:
            return

        contract = chain.contracts.get(self.entry_symbol)
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint < 1.50 * self.entry_price:
            return

        self._cancel_open_exit_order()
        quantity = self.portfolio[self.entry_symbol].quantity

        if quantity > 0:
            self.exit_reason = "profit target"
            self.exit_ticket = self.market_order(
                self.entry_symbol,
                -quantity
            )
            self.debug(
                f"Exit submitted: profit target, "
                f"{self.entry_symbol}, midpoint={midpoint:.4f}"
            )

    def _handle_time_stop(self):
        if self.entry_symbol is None or not self._has_option_position():
            return

        if self.exit_ticket is not None:
            return

        expiry_date = self.entry_symbol.id.date.date()
        previous_trading_day = (
            self.securities[self.spy]
            .exchange
            .hours
            .get_previous_trading_day(expiry_date)
            .date()
        )

        if (
            self.time.date() == previous_trading_day
            and self.time.time() >= dt_time(15, 45)
        ):
            quantity = self.portfolio[self.entry_symbol].quantity

            if quantity > 0:
