        if self.entry_symbol is not None:
            expiry_date = self.entry_symbol.id.date.date()

            if now.date() >= expiry_date:
                self.blocked_entry_date = now.date()

                if self.entry_ticket is not None:
                    self.entry_ticket.cancel("Expiration processing")
                    self.entry_ticket = None

                if self._has_option_position() and self.exit_ticket is None:
                    quantity = self.portfolio[self.entry_symbol].quantity

                    if quantity > 0:
                        self.exit_reason = "expiration processing"
                        self.exit_ticket = self.market_order(
