                security.type == SecurityType.OPTION
                and security.quantity > 0
                and security.symbol.id.symbol == "SPY"
            ):
                return True
        return False

    def _cancel_open_exit_order(self):
        if self.exit_ticket is not None:
            status = self.exit_ticket.status
            if status in (
                OrderStatus.SUBMITTED,
                OrderStatus.PARTIALLY_FILLED,
                OrderStatus.NEW
            ):
                self.exit_ticket.cancel("Replaced by liquidation order")
            self.exit_ticket = None

    def on_order_event(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.order_id == self.entry_ticket.order_id:
                if order_event.status == OrderStatus.FILLED:
                    self.entry_price = float(order_event.fill_price)
                    self.entry_ticket = None
                    self.debug(
                        f"Entry filled: {order_event.symbol}, "
                        f"price={self.entry_price:.4f}"
                    )
                elif order_event.status in (
                    OrderStatus.CANCELED,
                    OrderStatus.INVALID,
                    OrderStatus.REJECTED
                ):
                    self.debug(
                        f"Entry order did not fill: "
                        f"{order_event.symbol}, status={order_event.status}"
                    )
                    self.entry_ticket = None
                    self.entry_symbol = None
                    self.entry_price = None
                return

        if self.exit_ticket is not None:
            if order_event.order_id == self.exit_ticket.order_id:
                if order_event.status == OrderStatus.FILLED:
                    self.debug(
                        f"Exit filled: {order_event.symbol}, "
                        f"reason={self.exit_reason}"
                    )
                    self.exit_ticket = None
                    self.entry_symbol = None
                    self.entry_price = None
                    self.exit_reason = None
                elif order_event.status in (
                    OrderStatus.CANCELED,
                    OrderStatus.INVALID,
                    OrderStatus.REJECTED
                ):
                    self.exit_ticket = None
                return

        if (
