from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyOptionMovingAverageCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ProcessExpiration
        )
        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.ProcessTimeStop
        )

    def OnData(self, slice: Slice):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug(f"{self.Time}: unexpected SPY equity position; liquidating")
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self.ProcessMinuteBar(bar, slice)

        self.ProcessProfitTarget(slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        end = self.Time.replace(second=0, microsecond=0)

        if end.time() <= TimeSpan.FromHours(9.5).ToTimeSpan():
            return

        if end.hour > 16 or (end.hour == 16 and end.minute > 0):
            return

        bucket_minute = ((end.minute - 1) // 5 + 1) * 5
        bucket_end = end.replace(minute=0) + timedelta(minutes=bucket_minute)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.EmitBucketIfComplete(slice)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end == bucket_end:
            self.EmitBucketIfComplete(slice)
            self.bucket_end = None
            self.bucket_bars = {}

    def EmitBucketIfComplete(self, slice: Slice):
        if self.bucket_end is None:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(timestamp not in self.bucket_bars for timestamp in expected):
            return

        bars = [self.bucket_bars[timestamp] for timestamp in reversed(expected)]

        consolidated_close = bars[-1].Close
        self.fast_closes.append(consolidated_close)
        self.slow_closes.append(consolidated_close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = self.bucket_end.time()
        eligible = (
            end_time >= TimeSpan.FromHours(9.75).ToTimeSpan() and
            end_time <= TimeSpan.FromHours(14.5).ToTimeSpan()
        )

        if bullish_cross and eligible:
            self.TryEnter(slice, consolidated_close)

    def TryEnter(self, slice: Slice, spy_price: float):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.IsTerminal(
            self.entry_ticket.Status
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - current_date).days >= 7
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no valid contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{self.Time}: entry submitted {selected.Symbol}"
        )

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def ProcessTimeStop(self):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        security = self.Securities.get(self.held_option)
        if security is None:
            return

        expiration = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if self.IsTradingDayImmediatelyBefore(current_date, expiration):
            self.SubmitExit("expiration time stop")

    def ProcessExpiration(self):
        self.no_entry_date = None

        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        security = self.Securities.get(self.held_option)
        if security is None:
            return

        if security.Symbol.ID.Date.date() <= self.Time.date():
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.IsTerminal(
            self.exit_ticket.Status
        ):
            return

        self.CancelOpenExitOrder()
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            f"{self.Time}: exit submitted ({reason}) {self.held_option}"
        )

    def CancelOpenExitOrder(self):
        if (
            self.exit_ticket is not None and
            not self.IsTerminal(self.exit_ticket.Status)
        ):
            self.exit_ticket.Cancel("replaced by liquidation")

    def IsTradingDayImmediatelyBefore(self, current_date, expiration):
        if current_date >= expiration:
            return False

        date = current_date + timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while date < expiration:
            if hours.IsDateOpen(date):
                return False
            date += timedelta(days=1)

        return date == expiration and hours.IsDateOpen(expiration)

    def IsTerminal(self, status):
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None and
