            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        chain = None
        for _, candidate_chain in slice.OptionChains.items():
            for contract in candidate_chain:
                if contract.Symbol == self.held_symbol:
                    chain = contract
                    break
            if chain is not None:
                break

        if chain is None:
            return

        bid = chain.BidPrice
        ask = chain.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
