        if spy_bar is not None:
            self._update_minute_bucket(spy_bar)

        self._evaluate_option_exits(slice)

    def _update_minute_bucket(self, bar: TradeBar):
        bar_time = bar.Time
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_date != self.bucket_date or not (
            time(9, 30) <= bar_clock < time(16, 0)
        ):
            if self.bucket_bars:
                self._discard_bucket()

            self.bucket_date = bar_date
            self.bucket_start = None
            self.bucket_bars = []

        minute = bar_time.minute

        if self.bucket_start is None:
            if minute % 5 != 0:
                return

            self.bucket_start = bar_time.replace(
                second=0,
                microsecond=0
            )
            self.bucket_bars = [bar]
            return

        expected_time = self.bucket_bars[-1].Time + timedelta(minutes=1)

        if bar_time != expected_time:
            self._discard_bucket()

            if minute % 5 != 0:
                return

            self.bucket_start = bar_time.replace(
                second=0,
                microsecond=0
            )
            self.bucket_bars = [bar]
            return

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            consolidated = self._make_consolidated_bar()
            self._discard_bucket()
            self._on_five_minute_bar(consolidated)

    def _make_consolidated_bar(self):
        bars = self.bucket_bars

        return TradeBar(
            self.bucket_start,
            self.spy,
            bars[0].Open,
            max(float(x.High) for x in bars),
            min(float(x.Low) for x in bars),
            bars[-1].Close,
