            if self._order_is_open(self.entry_ticket):
                self.entry_ticket.Cancel("Canceling entry at expiration processing.")

            self._submit_exit(
                "Expiration safeguard",
                cancel_existing=True
            )

    def _submit_exit(self, reason, cancel_existing=False):
        if self.held_symbol is None:
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

        if cancel_existing and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceling prior exit order.")
            self.exit_ticket = None

        if self._order_is_open(self.exit_ticket):
