    def _handle_unexpected_equity_position(self, today):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity == 0:
            return

        self.blocked_entry_date = today

        if not self._order_is_open(self.equity_liquidation_ticket):
            self.Debug(
                "Unexpected exercise/assignment created SPY position; "
                "liquidating immediately."
            )

            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _prior_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(
            datetime.combine(candidate, time(0, 0))
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
