        self._bucket_bars = {}

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_price = None

        self._held_symbol = None
        self._exit_ticket = None
        self._pending_signal = False
        self._no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position(today)

        if self._held_symbol is not None:
            self._process_expiration_and_time_stop(slice, today)
            self._process_profit_target(slice)

        self._process_spy_minute_bar(slice)

        if self._pending_signal:
            self._pending_signal = False
            self._try_enter(slice, today)

    def _process_spy_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy):
            return

        minute_bar = slice.Bars[self.spy]
        end_time = minute_bar.EndTime

        # Five-minute buckets aligned to New York clock boundaries.
        bucket_end = end_time.replace(
            second=0,
            microsecond=0,
            minute=((end_time.minute // 5) + 1) * 5
        )

        if self._bucket_end is None:
            self._bucket_end = bucket_end

        if bucket_end != self._bucket_end:
            self._complete_five_minute_bucket()
            self._bucket_bars = {}
            self._bucket_end = bucket_end

        self._bucket_bars[end_time] = minute_bar

    def _complete_five_minute_bucket(self):
        if self._bucket_end is None:
            return

        bucket_start = self._bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        # Missing minute data invalidates the entire five-minute bar.
        if any(t not in self._bucket_bars for t in expected_times):
            return

        bars = [self._bucket_bars[t] for t in expected_times]

        five_minute_bar = TradeBar(
            bucket_start,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(five_minute_bar.EndTime, five_minute_bar.Close)
        self.slow.Update(five_minute_bar.EndTime, five_minute_bar.Close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        bar_time = five_minute_bar.EndTime.time()
        if (
            bullish_cross and
            datetime.strptime("09:45", "%H:%M").time() <= bar_time <=
            datetime.strptime("14:30", "%H:%M").time()
        ):
            self._pending_signal = True

    def _try_enter(self, slice: Slice, today):
