            self.current_bar_date = bar_date

        # Regular-session five-minute bars:
        # 09:31-09:35, 09:36-09:40, ..., 15:56-16:00.
        session_start = datetime(
            bar_date.year, bar_date.month, bar_date.day, 9, 30
        )
