        if end < first_endpoint or end > datetime(
            bar_date.year, bar_date.month, bar_date.day, 16, 0
        ):
            return

        elapsed_minutes = int((end - first_endpoint).total_seconds() // 60)
        endpoint = first_endpoint + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        self.minute_bars.setdefault(endpoint, {})[end] = minute_bar

        if end != endpoint:
            return

        expected_times = [
            endpoint - timedelta(minutes=minutes)
            for minutes in range(4, -1, -1)
        ]
        bars = self.minute_bars.get(endpoint, {})

        # Do not synthesize a five-minute bar when any minute is missing.
        if any(timestamp not in bars for timestamp in expected_times):
            self.minute_bars.pop(endpoint, None)
