        expiration = min(contract.Expiry.date() for contract in contracts)

        current_price = float(spy_bar.Close)
        minimum_strike = 1.01 * current_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute MA crossover"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                expiration,
                selected.Strike
            )
        )

    def EvaluateOpenPosition(self, slice: Slice):
        if self.held_option is None:
            return

        today = self.Time.date()
        expiration = self.held_option.ID.Date.date()

        # Never intentionally carry the option into expiration.
        if today >= expiration:
            self.no_entry_date = today
            self.SubmitOptionExit("Expiration-day liquidation")
            return

        # Time stop on the trading day immediately preceding expiration.
        prior_trading_day = self.GetPriorTradingDay(expiration)

        if (
            today == prior_trading_day
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        ):
            self.SubmitOptionExit("Pre-expiration time stop")
            return

        contract_data = None
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is not None:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    contract_data = contract
                    break

        if contract_data is None:
            return

        bid = float(contract_data.BidPrice)
        ask = float(contract_data.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self.SubmitOptionExit("50 percent profit target")

    def SubmitOptionExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.CancelOpenExitOrders()

        ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.exit_tickets.append(ticket)

        self.Debug(
            "Exit submitted: {0}, quantity {1}".format(
                reason,
                quantity
            )
        )

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        if self.Time.date() >= self.held_option.ID.Date.date():
            self.no_entry_date = self.Time.date()
            self.SubmitOptionExit("Unexpected expiration processing")

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected: {0}".format(
                    quantity
                )
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        quantity = self.Portfolio[self.spy].Quantity

        self.Debug("Unexpected exercise or assignment processing detected")

        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_exit_date = (
                    self.held_option.ID.Date.date()
                )

                self.Debug(
                    "Entry filled: {0}, price {1}".format(
                        self.held_option,
                        self.entry_price
                    )
                )

            elif self.IsTerminal(order_event.Status):
                self.entry_ticket = None

        for ticket in list(self.exit_tickets):
            if order_event.OrderId != ticket.OrderId:
                continue

            if order_event.Status == OrderStatus.Filled:
                if (
                    self.held_option is not None
                    and self.Portfolio[self.held_option].Quantity == 0
                ):
                    self.Debug(
                        "Exit filled: {0}, price {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.expiration_exit_date = None
                    self.exit_tickets = []

            elif self.IsTerminal(order_event.Status):
                self.exit_tickets.remove(ticket)

    def CancelOpenExitOrders(self):
        for ticket in self.exit_tickets:
            if not self.IsTerminal(ticket.Status):
                ticket.Cancel("Superseded by liquidation order")

    def GetPriorTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsTerminal(status):
        return status in {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        }
