    def CancelOpenExitOrders(self):
        for ticket in self.exit_tickets:
            if not self.IsTerminal(ticket.Status):
                ticket.Cancel("Superseded by liquidation order")

    def GetPriorTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsTerminal(status):
        return status in {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        }

