class SpyOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None

        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.exit_submitted = False

        self.blocked_entry_date = None
        self.expiration_processed = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position(current_date)
        self._process_expiration()
        self._evaluate_open_position(slice)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime.astimezone(
            TimeZones.NewYork
        ) if minute_bar.EndTime.tzinfo else minute_bar.EndTime

        if local_end.weekday() >= 5:
            return

        end_minutes = local_end.hour * 60 + local_end.minute
        if end_minutes <= 9 * 60 + 30 or end_minutes > 16 * 60:
            return

        bucket_end_minute = ((end_minutes + 4) // 5) * 5
        bucket_date = local_end.date()
        bucket_end = datetime(
            bucket_date.year,
            bucket_date.month,
            bucket_date.day,
            bucket_end_minute // 60,
            bucket_end_minute % 60
        )

        if self.bucket_end != bucket_end:
            if self.bucket_end is not None:
                self._complete_bucket(slice)

            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_end] = minute_bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if all(expected_time in self.bucket_bars for expected_time in expected_times):
            self._complete_bucket(slice)

    def _complete_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        expected_times = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(expected_time in self.bucket_bars for expected_time in expected_times):
            self.bucket_end = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]

        consolidated_close = bars[-1].Close
        self.closes.append(consolidated_close)

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) >= self.slow_period:
            fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            slow = sum(self.closes[-self.slow_period:]) / self.slow_period

            bullish_cross = (
                self.previous_fast is not None and
                self.previous_slow is not None and
                self.previous_fast <= self.previous_slow and
                fast > slow
            )

            bar_end_time = self.bucket_end.time()
            eligible_time = (
                time(9, 45) <= bar_end_time <= time(14, 30)
            )

            if bullish_cross and eligible_time:
                self._try_enter(slice, consolidated_close)

            self.previous_fast = fast
            self.previous_slow = slow

        self.bucket_end = None
        self.bucket_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

