from datetime import datetime, timedelta, time


class SpyOptionMovingAverageAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol

        # Broad weekly-inclusive universe.
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.current_bucket_end = None
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None
        self.bucket_volume = 0

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None

        self.no_entry_date = None
        self.last_equity_warning_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_date is not None and self.no_entry_date != today:
            self.no_entry_date = None

        self._handle_unexpected_equity_position(today)
        self._handle_expiration_processing(today)

        if self.held_symbol is not None and self._holding_exists():
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop(today)

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None and self._holding_exists():
            return

        if self.no_entry_date == today:
            return

        if not slice.Bars.ContainsKey(self.spy):
            return

        spy_bar = slice.Bars[self.spy]
        completed_bar = self._update_five_minute_bar(spy_bar)

        if completed_bar is None:
            return

        self.closes.Add(float(completed_bar.Close))

        if not self.closes.IsReady:
            return

        fast_current = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period

        slow_current = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        if self.closes.Count < self.slow_period:
            return

        previous_values = [
            self.closes[i] for i in range(1, self.slow_period)
        ]

        fast_previous = sum(
            previous_values[i] for i in range(self.fast_period)
        ) / self.fast_period

        slow_previous = sum(previous_values) / self.slow_period

        bar_end_local = completed_bar.EndTime
        if not (time(9, 45) <= bar_end_local.time() <= time(14, 30)):
            return

        bullish_cross = (
            fast_previous <= slow_previous
            and fast_current > slow_current
        )

        if bullish_cross:
            self._try_enter(slice, float(completed_bar.Close), today)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.Time
        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return None

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
        ) - (9 * 60 + 30)

        bucket_end_minutes = (
            ((minutes_from_open // 5) + 1) * 5
        )
        bucket_end = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            9,
            30
        ) + timedelta(minutes=bucket_end_minutes)

        completed = None

        if self.current_bucket_end is not None:
            if bucket_end != self.current_bucket_end:
                completed = TradeBar(
                    self.current_bucket_end - timedelta(minutes=5),
                    self.spy,
                    self.bucket_open,
                    self.bucket_high,
                    self.bucket_low,
                    self.bucket_close,
                    self.bucket_volume,
                    timedelta(minutes=5)
                )

                self.bucket_open = None
                self.bucket_high = None
                self.bucket_low = None
                self.bucket_close = None
                self.bucket_volume = 0

        if self.bucket_open is None:
            self.bucket_open = minute_bar.Open
            self.bucket_high = minute_bar.High
            self.bucket_low = minute_bar.Low
            self.bucket_close = minute_bar.Close
            self.bucket_volume = minute_bar.Volume
        else:
            self.bucket_high = max(self.bucket_high, minute_bar.High)
            self.bucket_low = min(self.bucket_low, minute_bar.Low)
            self.bucket_close = minute_bar.Close
            self.bucket_volume += minute_bar.Volume

        self.current_bucket_end = bucket_end
        return completed

    def _try_enter(self, slice: Slice, spy_price: float, today):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = today + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible option contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)

        eligible = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {nearest_expiry}, strike {selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        held_contract = None

        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self.held_symbol):
                held_contract = chain.Contracts[self.held_symbol]
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -abs(self.Portfolio[self.held_symbol].Quantity)
            )
            self.Debug(
                f"Profit target reached: {self.held_symbol.Value}, "
                f"midpoint {midpoint:.2f}"
            )

    def _evaluate_time_stop(self, today):
        if self.held_symbol is None or self.held_expiry is None:
            return

        preceding_trading_day = self._previous_trading_day(self.held_expiry)

        if today != preceding_trading_day or self.Time.time() < time(15, 45):
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -abs(quantity)
        )

        self.Debug(
            f"Time-stop exit submitted: {self.held_symbol.Value}"
        )

    def _handle_expiration_processing(self, today):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if today >= self.held_expiry:
            self.no_entry_date = today

            if self.exit_ticket is None or not self._ticket_is_open(self.exit_ticket):
                quantity = self.Portfolio[self.held_symbol].Quantity
                if quantity != 0:
                    self.exit_ticket = self.MarketOrder(
                        self.held_symbol,
                        -abs(quantity)
                    )
                    self.Debug(
                        f"Unexpected expiration handling: "
                        f"liquidation submitted for {self.held_symbol.Value}"
                    )

    def _handle_unexpected_equity_position(self, today):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.no_entry_date = today

            if self.last_equity_warning_date != today:
                self.Debug(
                    f"Unexpected exercise or assignment: "
                    f"liquidating {quantity} SPY shares."
                )
                self.last_equity_warning_date = today

