                .Strikes(-200, 200)
                .Expiration(timedelta(0), timedelta(days=730))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.current_group_start = None
        self.current_group_bars = []

        self.entry_order_id = None
        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.exit_order_id = None
        self.exit_ticket = None

        self.blocked_entry_date = None
        self.time_stop_dates = {}

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration()
        self._evaluate_held_position(data)

        spy_bar = self._get_spy_bar(data)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, data)

    def _get_spy_bar(self, data):
        try:
            if data.Bars.ContainsKey(self.spy):
                return data.Bars[self.spy]
        except Exception:
            try:
                return data.Bars.get(self.spy)
            except Exception:
                pass
        return None

    def _process_minute_bar(self, bar, data):
        bar_time = bar.Time.replace(second=0, microsecond=0)
        local_date = bar_time.date()
        local_clock = bar_time.time()

        if local_clock < time(9, 30) or local_clock >= time(16, 0):
            return

        group_minute = ((bar_time.minute - 30) // 5) * 5 + 30
        group_start = bar_time.replace(minute=group_minute)

        if self.current_group_start is None:
            self.current_group_start = group_start

        if group_start != self.current_group_start:
            self._finalize_five_minute_group(data)
            self.current_group_start = group_start
            self.current_group_bars = []

        self.current_group_bars.append(bar)

        if len(self.current_group_bars) == 5:
            self._finalize_five_minute_group(data)
            self.current_group_start = None
            self.current_group_bars = []

    def _finalize_five_minute_group(self, data):
        bars = self.current_group_bars
        if len(bars) != 5 or self.current_group_start is None:
            return

        expected_times = [
            self.current_group_start + timedelta(minutes=i)
            for i in range(5)
        ]

        actual_times = [
            bar.Time.replace(second=0, microsecond=0)
            for bar in bars
        ]

        if actual_times != expected_times:
            return

        close = bars[-1].Close
        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        completed_end = self.current_group_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= completed_end.time() <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_crossover and eligible_time:
            self._try_enter(data, close)

    def _try_enter(self, data, spy_price):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.entry_order_id is not None:
            return

        if self._has_option_holding():
            return

        if self.held_symbol is not None:
            return

        chain = None
        try:
            if data.OptionChains.ContainsKey(self.spy_option):
                chain = data.OptionChains[self.spy_option]
        except Exception:
            try:
                chain = data.OptionChains.get(self.spy_option)
            except Exception:
                chain = None

        if chain is None:
            self.Debug("Skipped option selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug("Skipped option selection: no expiration at least seven days out.")
            return

        nearest_expiry = min(
            contract.Expiry.date()
            for contract in eligible_contracts
        )

        target_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= target_strike
        ]

        if not candidates:
            self.Debug("Skipped option selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

    def _evaluate_held_position(self, data):
        if self.held_symbol is None or self.entry_price is None:
            return

        security = self.Securities[self.held_symbol]
        if not self.Portfolio[self.held_symbol].Invested:
            return

        current_date = self.Time.date()
        expiry_date = security.Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_exit("Expiration protection")
            return

        time_stop_date = self._get_previous_trading_day(expiry_date)
        if (
            current_date == time_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        contract = self._get_current_contract_quote(data, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * float(self.entry_price):
            self._submit_exit("50 percent profit target")

    def _get_current_contract_quote(self, data, symbol):
        try:
            if not data.OptionChains.ContainsKey(self.spy_option):
                return None
            chain = data.OptionChains[self.spy_option]
        except Exception:
            try:
                chain = data.OptionChains.get(self.spy_option)
            except Exception:
                return None

        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.exit_ticket.Cancel("Superseded by exit condition")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_symbol,
                reason
            )
        )

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_exit("Expiration processing protection")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug(
            "Unexpected SPY equity position detected, likely exercise or assignment. "
            "Liquidating entire SPY position."
        )
        self.Liquidate(self.spy, "Unexpected exercise or assignment")

        self.blocked_entry_date = self.Time.date()

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if security.Type != SecurityType.Option:
                continue

            if self.Portfolio[security.Symbol].Quantity != 0:
                return True

        return False

    def _get_previous_trading_day(self, expiry_date):
        if expiry_date in self.time_stop_dates:
            return self.time_stop_dates[expiry_date]

        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while True:
            try:
                is_open = exchange_hours.IsDateOpen(candidate)
            except Exception:
                is_open = candidate.weekday() < 5

            if is_open:
                self.time_stop_dates[expiry_date] = candidate
                return candidate

            candidate -= timedelta(days=1)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                order = self.Transactions.GetOrderById(order_event.OrderId)
                self.held_symbol = order.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

                self.entry_order_id = None
                self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_order_id = None
                self.entry_ticket = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        self.held_symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_order_id = None
                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_order_id = None
                self.exit_ticket = None
