        bucket_minutes = ((minutes_from_open + 4) // 5) * 5
        bucket_end = session_start + timedelta(minutes=bucket_minutes)

        if self.bucket_date != end.date() or self.bucket_end != bucket_end:
            if self.bucket_end is not None:
                self._finalize_five_minute_bar(slice)

            self.bucket_date = end.date()
            self.bucket_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[end] = minute_bar

        if end == bucket_end:
            self._finalize_five_minute_bar(slice)
            self.bucket_end = None
            self.minute_bars = {}

    def _finalize_five_minute_bar(self, slice):
        if self.bucket_end is None:
            return

        expected = {
            self.bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        if set(self.minute_bars.keys()) != expected:
            return

        close = self.minute_bars[self.bucket_end].Close

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
