        symbol = self._get_option_holding()
        if symbol is None:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()

            if self.entry_ticket is not None and self._ticket_open(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing began.")

            quantity = int(self.Portfolio[symbol].Quantity)
            if quantity > 0:
                self._submit_option_exit(
                    symbol,
                    quantity,
                    "Unexpected option position at expiration"
                )

    def _submit_option_exit(self, symbol, quantity, reason):
        if self._ticket_open_any_exit():
            return

        self._cancel_open_exit_orders()
        ticket = self.MarketOrder(symbol, -quantity, tag=reason)
        self.exit_tickets.append(ticket)

    def _find_current_contract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _get_option_holding(self):
        for security in self.Portfolio.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and security.Quantity > 0
            ):
                return security.Symbol
        return None

    def _handle_unexpected_spy_equity(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is None
            or not self._ticket_open(self.equity_cleanup_ticket)
        ):
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy_symbol,
                -int(holding.Quantity),
                tag="Unexpected exercise or assignment cleanup"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time(0, 0))
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_open(self, ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _ticket_open_any_exit(self):
        return any(self._ticket_open(ticket) for ticket in self.exit_tickets)

    def _cancel_open_exit_orders(self):
        for ticket in self.exit_tickets:
            if self._ticket_open(ticket):
                ticket.Cancel("Profit target reached; canceling other exit.")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entered {self.held_option} at fill price "
                    f"{self.entry_fill_price:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if order_event.Status == OrderStatus.Filled:
            for ticket in self.exit_tickets:
                if ticket.OrderId == order_event.OrderId:
                    self.Debug(
                        f"Exited {order_event.Symbol}: "
                        f"{ticket.Tag or 'market exit'}."
                    )
                    self.exit_tickets = []
                    self.held_option = None
                    self.entry_fill_price = None
                    break
