        if self._has_open_entry_order() or self._has_option_holding():
            self._update_spy_bar(slice)
            return

        self._update_spy_bar(slice)

    def _update_spy_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end_time = self._minute_time(self.Time)
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        session_start = end_time.replace(hour=9, minute=30, second=0, microsecond=0)
        elapsed_minutes = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (elapsed_minutes + 4) // 5
        bucket_end = session_start + timedelta(minutes=5 * bucket_number)

        if self._bucket_end is None:
            self._bucket_end = bucket_end
            self._bucket_bars = [bar]
            return

        if bucket_end != self._bucket_end:
            if len(self._bucket_bars) == 5:
                self._process_five_minute_bar(self._bucket_bars)

            self._bucket_end = bucket_end
            self._bucket_bars = [bar]
            return

        expected_next = self._minute_time(self._bucket_bars[-1].EndTime) + timedelta(minutes=1)

        if end_time != expected_next:
            self._bucket_bars = [bar]
            return

        self._bucket_bars.append(bar)

        if len(self._bucket_bars) == 5:
            self._process_five_minute_bar(self._bucket_bars)

    def _process_five_minute_bar(self, bars):
        closes = [float(bar.Close) for bar in bars]
        current_close = closes[-1]

        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.closes.append(current_close)

        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
        else:
            current_fast = None

        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0
        else:
            current_slow = None

        bar_end = self._minute_time(bars[-1].EndTime)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            bullish_cross
            and eligible_time
            and self._current_slice is not None
            and self._no_entry_date != self.Time.date()
            and not self._has_open_entry_order()
            and not self._has_option_holding()
        ):
            self._try_enter_option(self._current_slice, current_close)

    def _try_enter_option(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains.Values)

        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = self._date_value(contract.Expiry)

                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying option contract.")
            return

        nearest_expiry = min(self._date_value(c.Expiry) for c in contracts)
        candidates = [
            c for c in contracts
            if self._date_value(c.Expiry) == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {0}, expiry={1}, strike={2}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def _handle_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        contract = self._find_contract(slice, self._held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("profit target")

    def _handle_time_stop(self):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        security = self.Securities[self._held_symbol]
        expiry_date = self._date_value(security.Symbol.ID.Date)

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self._date_value(
            self.Securities[self._held_symbol].Symbol.ID.Date
        )

        if self.Time.date() >= expiry_date:
            self._no_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        quantity = int(holding.Quantity)

        if quantity <= 0 or self._has_open_exit_order():
            return

        self._cancel_open_exit_order()
        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity
        )

        self.Debug(
            "Exit submitted: {0}, symbol={1}".format(
                reason, self._held_symbol
            )
        )

    def _handle_unexpected_spy_equity(self):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity == 0:
            return

        if self._equity_exit_ticket is not None and self._is_open(
            self._equity_exit_ticket
        ):
            return

        self.Debug(
            "Unexpected exercise or assignment handling: liquidating SPY equity."
        )

        self._equity_exit_ticket = self.MarketOrder(self.spy, -quantity)
        self._no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None

                self.Debug(
                    "Entry filled: {0}, price={1}".format(
                        self._held_symbol, self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected exercise or assignment event: {0}".format(
                    order_event.Symbol
                )
            )
            self._no_entry_date = self.Time.date()

    def _find_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _has_option_holding(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Quantity > 0
        )

    def _has_open_entry_order(self):
        return (
            self._entry_ticket is not None
            and self._is_open(self._entry_ticket)
        )

    def _has_open_exit_order(self):
        return (
            self._exit_ticket is not None
            and self._is_open(self._exit_ticket)
        )

    def _cancel_open_exit_order(self):
        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing exit order")

    def _is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            candidate
        ):
