        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol

        # Broad universe for weekly and standard contracts.
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0

        self.current_bucket_end = None
        self.current_minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option_symbol = None
        self.entry_price = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_held_option(slice)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        completed_bar = self._add_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self._update_moving_averages(completed_bar.Close)

        bar_end = completed_bar.EndTime.time()
        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self._has_option_position() or self._entry_order_is_open():
            return

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = self.fast_sum / 5.0
        current_slow = self.slow_sum / 20.0

        # Previous values are available because the current bar was just added.
        previous_fast = (
            sum(list(self.fast_values)[:-1]) / 5.0
            if len(self.fast_values) == 5
            else None
        )
        previous_slow = (
            sum(list(self.slow_values)[:-1]) / 20.0
            if len(self.slow_values) == 20
            else None
        )

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter_option(slice, completed_bar.Close)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = order_event.FillPrice
                    self.held_option_symbol = order_event.Symbol
                    self.Debug(
                        f"Entry filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug(
                        f"Entry order did not fill: "
                        f"{order_event.Status}"
                    )
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                    self.exit_ticket = None
                    self.entry_price = None
                    self.held_option_symbol = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

        self._handle_unexpected_equity_position()

    def _add_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        session_start = end_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = end_time.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if end_time <= session_start or end_time > session_end:
            return None

        minutes_from_open = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = session_start + timedelta(minutes=bucket_number * 5)

        completed = None

        if (
            self.current_bucket_end is not None
            and bucket_end != self.current_bucket_end
        ):
            completed = self._finalize_bucket()
            self.current_minute_bars = {}

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end

        minute_key = end_time.replace(second=0, microsecond=0)
        self.current_minute_bars[minute_key] = bar

        if end_time == bucket_end:
            finalized = self._finalize_bucket()
            self.current_minute_bars = {}
            self.current_bucket_end = None
            return finalized

        return completed

    def _finalize_bucket(self):
        if self.current_bucket_end is None:
            return None

        bucket_start = self.current_bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(t not in self.current_minute_bars for t in expected_times):
            # Missing minute data means the five-minute bar is invalid.
            return None

        bars = [self.current_minute_bars[t] for t in expected_times]

        return TradeBar(
            self.current_bucket_end - timedelta(minutes=5),
            self.spy_symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _update_moving_averages(self, close):
        if len(self.fast_values) == self.fast_values.maxlen:
            self.fast_sum -= self.fast_values[0]
        self.fast_values.append(close)
        self.fast_sum += close

        if len(self.slow_values) == self.slow_values.maxlen:
            self.slow_sum -= self.slow_values[0]
        self.slow_values.append(close)
        self.slow_sum += close

    def _try_enter_option(self, slice, spy_price):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        current_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() - current_date >= timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        nearest_expiry_date = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_threshold = spy_price * 1.01
        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry_date
            and contract.Strike >= strike_threshold
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike satisfies the 1% OTM rule"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _process_held_option(self, slice: Slice):
        if self.held_option_symbol is None:
            return

        holding = self.Portfolio[self.held_option_symbol]
        if holding.Quantity <= 0:
            return

        expiry = self.Securities[self.held_option_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        # Never intentionally hold through expiration.
        if current_date >= expiry:
            self.blocked_entry_date = current_date
            self.Debug(
                f"Unexpected expiration processing for "
                f"{self.held_option_symbol}"
            )
            self._submit_option_exit(
                holding.Quantity,
                "Expiration liquidation"
            )
            return

        prior_trading_day = self._prior_trading_day(expiry)
        if (
            current_date == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit(
                holding.Quantity,
                "Pre-expiration time stop"
            )
            return

        contract = self._get_current_contract(slice)
        if contract is None:
            return

        bid = getattr(contract, "BidPrice", 0)
        ask = getattr(contract, "AskPrice", 0)

