        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = self.fast_sum / 5.0
        current_slow = self.slow_sum / 20.0

        # Previous values are available because the current bar was just added.
        previous_fast = (
            sum(list(self.fast_values)[:-1]) / 5.0
            if len(self.fast_values) == 5
            else None
        )
        previous_slow = (
            sum(list(self.slow_values)[:-1]) / 20.0
            if len(self.slow_values) == 20
            else None
        )

