    def _add_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        session_start = end_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = end_time.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if end_time <= session_start or end_time > session_end:
            return None

        minutes_from_open = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = session_start + timedelta(minutes=bucket_number * 5)

        completed = None

        if (
            self.current_bucket_end is not None
            and bucket_end != self.current_bucket_end
        ):
            completed = self._finalize_bucket()
            self.current_minute_bars = {}

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end

        minute_key = end_time.replace(second=0, microsecond=0)
        self.current_minute_bars[minute_key] = bar

        if end_time == bucket_end:
            finalized = self._finalize_bucket()
            self.current_minute_bars = {}
            self.current_bucket_end = None
            return finalized

        return completed

    def _finalize_bucket(self):
        if self.current_bucket_end is None:
            return None

        bucket_start = self.current_bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(t not in self.current_minute_bars for t in expected_times):
            # Missing minute data means the five-minute bar is invalid.
            return None

        bars = [self.current_minute_bars[t] for t in expected_times]

        return TradeBar(
            self.current_bucket_end - timedelta(minutes=5),
            self.spy_symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

