        self.closes = []
        self.current_bucket = None
        self.current_bar = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.no_entries_date = None

    def OnData(self, slice):
        today = self.Time.date()

        # Immediately remove unexpected SPY equity positions, including assignment.
        equity_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if equity_quantity != 0:
            self.no_entries_date = today
            if not self._order_is_open(self.exit_ticket):
                self.Debug(
                    f"Unexpected exercise/assignment: liquidating "
                    f"{equity_quantity} SPY shares."
                )
                self.exit_ticket = self.MarketOrder(
                    self.spy.Symbol, -equity_quantity
                )
            return

        # Never intentionally hold an option into expiration.
        if self.held_symbol is not None and self.held_expiry is not None:
            if today >= self.held_expiry.date():
                self.no_entries_date = today
                self._submit_exit("expiration processing")

        # Evaluate the held option on every minute Slice.
        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_profit_target(slice)

            if self._is_pre_expiration_trading_day(today):
                if self.Time.time() >= datetime.strptime(
                    "15:45", "%H:%M"
                ).time():
                    self._submit_exit("pre-expiration time stop")

        # Build a clock-aligned five-minute bar from minute SPY data.
        if self.spy.Symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy.Symbol]
        local_time = self.Time

        if not (local_time.time() >= datetime.strptime("09:30", "%H:%M").time()
                and local_time.time() < datetime.strptime("16:00", "%H:%M").time()):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket = local_time.replace(
            minute=bucket_minute, second=0, microsecond=0
        )

        if self.current_bucket != bucket:
            self._finish_bucket()
            self.current_bucket = bucket
            self.current_bar = {
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume
            }
        else:
            self.current_bar["high"] = max(
                self.current_bar["high"], minute_bar.High
            )
            self.current_bar["low"] = min(
                self.current_bar["low"], minute_bar.Low
            )
            self.current_bar["close"] = minute_bar.Close
            self.current_bar["volume"] += minute_bar.Volume

        # A minute bar at xx:04 completes the five-minute bar ending xx:05.
        if local_time.minute % 5 == 4:
            self._finish_bucket()

    def _finish_bucket(self):
        if self.current_bucket is None or self.current_bar is None:
            return

        end_time = self.current_bucket + timedelta(minutes=5)
        close = self.current_bar["close"]

        prior_ready = len(self.closes) >= 20
        bullish_cross = False

        if prior_ready:
            prior_fast = sum(self.closes[-5:]) / 5.0
            prior_slow = sum(self.closes[-20:]) / 20.0

            candidate_closes = self.closes + [close]
            current_fast = sum(candidate_closes[-5:]) / 5.0
            current_slow = sum(candidate_closes[-20:]) / 20.0

            bullish_cross = (
                prior_fast <= prior_slow
                and current_fast > current_slow
            )

        self.closes.append(close)

        if len(self.closes) > 20:
            self.closes.pop(0)

        self.current_bucket = None
        self.current_bar = None

        if bullish_cross:
            end_clock = end_time.time()
            eligible_start = datetime.strptime("09:45", "%H:%M").time()
            eligible_end = datetime.strptime("14:30", "%H:%M").time()

            if eligible_start <= end_clock <= eligible_end:
                self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if self.no_entries_date == today:
            return

        if self.held_symbol is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if self._order_is_open(self.exit_ticket):
            return

        if self.spy.Symbol not in self.Securities:
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = None
        if self.option.Symbol in self.CurrentSlice.OptionChains:
            chain = self.CurrentSlice.OptionChains[self.option.Symbol]

        if chain is None:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug(
                "Skipped selection: no qualifying expiration or contract."
            )
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in contracts
        )

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.held_symbol = selected.Symbol
        self.held_expiry = selected.Expiry
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected.Expiry.date()}; strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice):
        if self._order_is_open(self.exit_ticket):
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if self.held_symbol in chain.Contracts:
                contract = chain.Contracts[self.held_symbol]
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._order_is_open(self.entry_ticket):
            return

        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")
        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity
        )

    def _is_pre_expiration_trading_day(self, current_date):
        if self.held_expiry is None:
            return False

        expiry_date = self.held_expiry.date()
        if current_date >= expiry_date:
            return False

        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol}; "
                    f"price={self.entry_price}"
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"Entry canceled or invalid: {order_event.Symbol}")
                self.entry_ticket = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol}; "
                    f"price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
